// Cyrus Config Studio: the REAL dependencies of /api/cyrus/config/v1 and the page. SERVER ONLY. No new Nxeon imports:
// the studios' existing wiring (viewer = Cyrus access rule + studios gate, the Prisma studio store, the ModBuild
// chain reader) and the host seam (rate limit). The flag is CYRUS_CONFIG_STUDIO=1 (env, fail closed). Delivery to
// servers is NOT wired here: the orchestrator's deliverConfig exists, but there is no enqueue path for it yet (the same
// open owner item as CYRUS_DELIVERY); the API answers 501 for "deliver" until the worker wiring lands.
import { getHost } from "../host";
import { studioViewer } from "../studios/deps";
import { configSourceOf, prismaStudioStore } from "../studios/store-prisma";
import type { ConfigApiDeps } from "./http";
import type { ConfigServiceDeps } from "./service";
import { configStudioOn } from "./route";
import { createProject } from "../engine-core/store";

export function configServiceDeps(): ConfigServiceDeps {
  return {
    store: prismaStudioStore, source: configSourceOf,
    // Live-test fix (D): a plain plugin build's first settings save creates its project (a racing create = it exists now)
    ensureProject: async (userId, rootBuildId) => {
      try { return await createProject({ userId, game: "minecraft", rootBuildId }); } catch { return prismaStudioStore.projectForRoot(rootBuildId); }
    },
  };
}

/** Who may see the Config Studio: the studios viewer AND the flag. */
export async function configStudioViewer(env: Record<string, string | undefined> = process.env) {
  if (!configStudioOn(env)) return null;
  return studioViewer().catch(() => null);
}

export function configApiDeps(env: Record<string, string | undefined> = process.env): ConfigApiDeps {
  return {
    viewer: async () => { const v = await studioViewer().catch(() => null); return v ? { userId: v.userId, preview: v.preview } : null; },
    flagOn: () => configStudioOn(env),
    service: configServiceDeps(),
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(`cyrus:${key}`, { max, windowMs }),
  };
}
