// Cyrus Config Studio: the VALUES-ONLY edit path (server side; every dependency injected, no Nxeon import). One save =
// a new CyrusRevision of kind "config" + a CyrusProjectAsset (kind "config", key "values") holding the values, the
// patch and the resulting config.yml text. No model call, no build, no token charge. Delivery to a server goes through
// the delivery orchestrator (deliverConfig) when the host wires it; otherwise the save says it is not connected.
// The schema comes from (in order): the build's declared settings (re-validated), the gameplay designs (compiled again
// -> fromDesignerParams), or inference from the jar's config.yml. Ownership is checked on the project (fail closed).
import { createHash } from "node:crypto";
import type { StudioStore, AssetRow, RevRow } from "../studios/service";
import type { ManifestEntry } from "../engine-core/revisions";
import { compileMod } from "../designer/gameplay/compile";
import { canonical, validateConfigSpec, type ConfigSpec, type ConfigValues } from "./spec";
import { checkValues, defaultsOf, sameValue, type ValueIssue } from "./values";
import { appliesFor, changedFromDefaults, diffValues, matchingPreset, type Patch } from "./diff";
import { readValues, renderConfigYml, writeValues } from "./file";
import { inferSchema } from "./infer";
import { fromDesignerParams } from "./designer";
import { planConfigEdit, type ConfigEditPlan } from "./edit";
import { visualEffects, type VisualEffects } from "./visual";

export const CONFIG_VALUES_MIME = "application/vnd.cyrus.config-values+json";
export const CONFIG_TOOLCHAIN = "cyrus-config-studio 1";

export class ConfigError extends Error {
  constructor(public status: number, public code: string, message: string, public extra: Record<string, unknown> = {}) { super(message); }
}

/** What the host knows about the mod's newest build (read through the ModBuild seam). */
export type ConfigSource = {
  buildId: string; pluginName: string | null; mcVersion: string;
  /** config.yml / plugin.yml as shipped in the jar (null when absent) */
  configYml: string | null; pluginYml: string | null;
  /** The build's settings schema as the portal re-validated it (ModBuild.result.cyrusConfig). */
  declared: { source: "declared" | "inferred"; spec: unknown } | null;
};
export type ConfigDeliverInput = { userId: string; serverId: string; projectId: string; revisionId: string; pluginName: string; spec: ConfigSpec; values: ConfigValues; changed: string[] };
export type ConfigServiceDeps = {
  store: Pick<StudioStore, "projectForRoot" | "assets" | "revisions" | "addRevision" | "recordAsset">;
  source: (userId: string, rootBuildId: string) => Promise<ConfigSource | null>;
  /** The host's delivery (worker job). Absent = not connected here: saves still work, delivery answers 501. */
  deliver?: (i: ConfigDeliverInput) => Promise<{ ok: boolean; outcome: string; error?: string; notes?: string[] }>;
  now?: () => Date;
  /** Live-test fix (D): a plain plugin build has no Cyrus project yet (no assets were made); the first save creates it
   *  (the namespace is reserved then) instead of refusing. Absent = the old 409 no_project. */
  ensureProject?: (userId: string, rootBuildId: string) => Promise<Awaited<ReturnType<ConfigServiceDeps["store"]["projectForRoot"]>>>;
};

export type SchemaSource = "declared" | "designer" | "inferred" | "none";
export type ConfigHistoryItem = { revisionId: string; seq: number; createdAt: string; message: string | null; patch: Patch };
export type ConfigView = {
  project: { id: string; namespace: string } | null;
  pluginName: string | null; mcVersion: string; buildId: string;
  source: SchemaSource; spec: ConfigSpec | null; notes: string[];
  /** current values (the newest studio save, else the build's config.yml) */
  values: ConfigValues;
  /** values as the build shipped them */
  shipped: ConfigValues;
  defaults: ConfigValues;
  changedFromDefaults: string[];
  preset: string;
  headRevisionId: string | null;
  history: ConfigHistoryItem[];
  visual: VisualEffects | null;
  deliveryConnected: boolean;
};

const sha256 = (s: string) => createHash("sha256").update(s).digest("hex");
const iso = (d: Date | string) => new Date(d).toISOString();
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const ts = (d: Date | string) => new Date(d).getTime();

/** The newest valid design spec per key (asset rows kind "design"). */
function designSpecs(rows: readonly AssetRow[]): unknown[] {
  const by = new Map<string, AssetRow>();
  for (const r of rows) if (r.kind === "design" && obj(r.provenance).spec) { const cur = by.get(r.assetKey); if (!cur || ts(r.createdAt) >= ts(cur.createdAt)) by.set(r.assetKey, r); }
  return [...by.values()].sort((a, b) => (a.assetKey < b.assetKey ? -1 : 1)).map((r) => obj(r.provenance).spec);
}

export function resolveSchema(src: ConfigSource, rows: readonly AssetRow[], namespace: string): { source: SchemaSource; spec: ConfigSpec | null; notes: string[] } {
  const notes: string[] = [];
  if (src.declared) {
    const v = validateConfigSpec(src.declared.spec);
    if (v.ok) return { source: src.declared.source, spec: v.spec, notes };
    notes.push(`the build's settings schema does not validate any more (${v.errors[0]?.message}); using a fallback`);
  }
  const designs = designSpecs(rows);
  if (designs.length && src.pluginName) {
    const c = compileMod(designs, { version: src.mcVersion, namespace, pluginName: src.pluginName });
    if (c.ok) {
      const r = fromDesignerParams(c.params, { command: c.command });
      if (r.ok) { if (r.skipped.length) notes.push(`${r.skipped.length} designer setting(s) cannot be edited here`); return { source: "designer", spec: r.spec, notes }; }
    } else notes.push("the designs no longer compile for this version; using the config file instead");
  }
  if (src.configYml) {
    const r = inferSchema(src.configYml, { pluginYml: src.pluginYml ?? undefined });
    if (r.ok) return { source: "inferred", spec: r.spec, notes: [...notes, ...r.notes.slice(0, 6)] };
    notes.push(...r.errors.slice(0, 3));
  }
  return { source: "none", spec: null, notes: [...notes, "this mod has no settings Cyrus can edit"] };
}

type ValuesRow = { row: AssetRow; values: ConfigValues; configYml: string; patch: Patch; specSha256: string };
function valuesRows(rows: readonly AssetRow[]): ValuesRow[] {
  return rows.filter((r) => r.kind === "config" && r.assetKey === "values" && r.mime === CONFIG_VALUES_MIME)
    .map((r) => { const p = obj(r.provenance); return { row: r, values: obj(p.values) as ConfigValues, configYml: typeof p.configYml === "string" ? p.configYml : "", patch: Array.isArray(p.patch) ? (p.patch as Patch) : [], specSha256: String(p.specSha256 ?? "") }; })
    .sort((a, b) => ts(a.row.createdAt) - ts(b.row.createdAt) || (a.row.id < b.row.id ? -1 : 1));
}

async function context(deps: ConfigServiceDeps, userId: string, rootBuildId: string) {
  const src = await deps.source(userId, rootBuildId);
  if (!src) throw new ConfigError(404, "not_found", "Mod not found.");
  const project = await deps.store.projectForRoot(rootBuildId);
  if (project && project.userId !== userId) throw new ConfigError(404, "not_found", "Mod not found.");
  const rows = project ? await deps.store.assets(project.id) : [];
  const schema = resolveSchema(src, rows, project?.namespace ?? "nx_00000000");
  const vrows = valuesRows(rows);
  return { src, project, rows, schema, vrows };
}

