export type SaveInput = { userId: string; rootBuildId: string; values: Record<string, unknown>; expectedHeadId: string | null; message?: string };
export type SaveResult = { revisionId: string; seq: number; patch: Patch; applies: string; configYml: string; warnings: ValueIssue[] };

/** Save new values as a revision (values only). A stale editor (expectedHeadId) is a 409, never an overwrite. */
export async function saveConfigValues(deps: ConfigServiceDeps, i: SaveInput): Promise<SaveResult> {
  const ctx = await context(deps, i.userId, i.rootBuildId);
  const { src, schema, vrows } = ctx;
  const project = ctx.project ?? (deps.ensureProject ? await deps.ensureProject(i.userId, i.rootBuildId).catch(() => null) : null);
  if (!project) throw new ConfigError(409, "no_project", "This mod has no Cyrus project yet, so its settings cannot be saved as a revision.");
  if (project.userId !== i.userId) throw new ConfigError(404, "not_found", "Mod not found.");
  const p = computeSave(schema.spec, src, vrows, i.values);
  if (p.errors.length) throw new ConfigError(422, "invalid_values", p.errors[0].message, { errors: p.errors.slice(0, 20) });
  if (!p.patch.length) throw new ConfigError(409, "no_change", "Nothing changed.");
  const revs = await deps.store.revisions(project.id);
  const head = revs[revs.length - 1] ?? null;
  if ((head?.id ?? null) !== (i.expectedHeadId ?? null)) throw new ConfigError(409, "stale_head", "This mod changed since you opened it. Reload to see the newest settings.", { headRevisionId: head?.id ?? null });
  const spec = schema.spec!;
  const values = p.values!;
  const ymlSha = sha256(p.configYml);
  const manifest: ManifestEntry[] = [...(head?.manifest ?? []).filter((e) => e.path !== "src/main/resources/config.yml"), { path: "src/main/resources/config.yml", sha256: ymlSha, role: "config" }];
  const byKey = new Map(spec.params.map((x) => [x.key, x]));
  const summary = p.patch.slice(0, 3).map((op) => byKey.get(op.key)?.label ?? op.key).join(", ");
  const message = (i.message?.trim() || `Changed ${p.patch.length} setting${p.patch.length > 1 ? "s" : ""}: ${summary}${p.patch.length > 3 ? ", ..." : ""}`).slice(0, 200);
  const rev = await deps.store.addRevision(project.id, { kind: "config", manifest, status: "passed", expectedHeadId: head?.id ?? null, engine: { toolchain: CONFIG_TOOLCHAIN }, message });
  const specSha256 = sha256(canonical(spec));
  const payload = canonical({ values, patch: p.patch, revisionId: rev.id });
  await deps.store.recordAsset(project.id, {
    revisionId: rev.id, assetKey: "values", kind: "config", sha256: sha256(payload), size: Buffer.byteLength(payload), origin: "edited", mime: CONFIG_VALUES_MIME, path: "src/main/resources/config.yml",
    provenance: { generator: CONFIG_TOOLCHAIN, values, patch: p.patch, configYml: p.configYml, configYmlSha256: ymlSha, specSha256, schemaSource: schema.source, buildId: src.buildId, applies: p.applies },
  });
  return { revisionId: rev.id, seq: rev.seq, patch: p.patch, applies: p.applies, configYml: p.configYml, warnings: p.warnings };
}

/** Undo: a NEW revision with the values before `revisionId` (history is never edited). */
export async function revertConfig(deps: ConfigServiceDeps, i: { userId: string; rootBuildId: string; revisionId: string; expectedHeadId: string | null }): Promise<SaveResult> {
  const { src, schema, vrows } = await context(deps, i.userId, i.rootBuildId);
  const idx = vrows.findIndex((v) => v.row.revisionId === i.revisionId);
  if (idx < 0 || !schema.spec) throw new ConfigError(404, "not_found", "That settings revision is not in this mod.");
  const before = idx > 0 ? vrows[idx - 1].values : src.configYml ? readValues(schema.spec, src.configYml).values : defaultsOf(schema.spec);
  return saveConfigValues(deps, { userId: i.userId, rootBuildId: i.rootBuildId, values: before, expectedHeadId: i.expectedHeadId, message: `Undid revision ${i.revisionId.slice(0, 8)}` });
}

/** Deliver the current values to one of the owner's servers (needs the host's delivery wiring). */
export async function deliverConfigValues(deps: ConfigServiceDeps, i: { userId: string; rootBuildId: string; serverId: string }) {
  if (!deps.deliver) throw new ConfigError(501, "delivery_not_connected", "Sending settings to a server is not connected here yet. Your settings are saved; they go out with the next install or update.");
  const v = await configView(deps, i.userId, i.rootBuildId);
  if (!v.spec || !v.project || !v.pluginName) throw new ConfigError(409, "no_settings", "This mod has no settings Cyrus can deliver.");
  const changed = v.spec.params.filter((p) => !sameValue(v.values[p.key], v.shipped[p.key])).map((p) => p.key);
  const head = v.history[0];
  return deps.deliver({ userId: i.userId, serverId: i.serverId, projectId: v.project.id, revisionId: head?.revisionId ?? v.headRevisionId ?? "none", pluginName: v.pluginName, spec: v.spec, values: v.values, changed: changed.length ? changed : v.spec.params.map((p) => p.key) });
}

/** The command box: "set the walk speed to 0.3 and health to 40" -> edits (no model), or why it needs the model. */
export async function planConfig(deps: ConfigServiceDeps, userId: string, rootBuildId: string, text: string): Promise<ConfigEditPlan> {
  const v = await configView(deps, userId, rootBuildId);
  if (!v.spec) return { kind: "model", reason: "this mod has no settings" };
  return planConfigEdit(text, v.spec, v.values);
}

// Cyrus wiring phase 2: the delivery JOB body (worker side), host-neutral. worker/cyrus-delivery.ts supplies Nxeon's
// deps (database rows, the SSH-backed DeliveryHost, the install row update); tests and the node-2 real run supply
// in-memory ones. Flow for one GAME_MOD_SYNC job carrying the `cyrusDelivery` payload:
//   payload valid? -> CYRUS_DELIVERY=1 in THIS process? -> server exists -> the subject belongs to the server's owner
//   -> assemble + verify the release from the stored build (releaseFromBuild), or open + verify the stored Mod Pack
//   version (and require every open warning acknowledged) -> the orchestrator (deliverMod / uninstallMod /
//   deliverModPack / uninstallModPack) -> store the compact result on the job -> move the install row to its final state (restored to its
//   previous state when the delivery was refused or rolled back) -> audit -> throw when it did not succeed (the job
//   is then FAILED, never retried: a retry would only repeat a refusal or a rollback).
import { deliverMod, deliverModPack, uninstallMod, uninstallModPack } from "./orchestrator";
import { releaseFromBuild, type BuildFacts, type DatapackAssetRow } from "./release";
import { DELIVERY_FLAG } from "./plan";
import { compactResult, readDeliveryPayload, type DeliveryPayload, type PackRef } from "./request";
import type { NxPack } from "../modpack/manifest";
import type { DeliveryHost, DeliveryResult, Env } from "./types";
import { notifyInstallResult } from "../notify/hooks";

export type DeliveryJob = { id: string; serverId: string | null; payload: unknown };
export type DeliveryBuildRow = BuildFacts & { userId: string; status: string; jarPath: string | null };
export type DeliveryServerRow = { id: string; userId: string };

export type InstallRowUpdate =
  | { kind: "delivered"; serverModId: string; buildId: string; jarName: string | null }
  | { kind: "removed"; serverModId: string }
  | { kind: "restore"; serverModId: string; prev: { status: string; versionId: string | null }; error: string }
  | { kind: "failed"; serverModId: string; error: string };

export type DeliveryJobDeps<S extends DeliveryServerRow = DeliveryServerRow> = {
  env: Env;
  server(serverId: string): Promise<S | null>;
  build(buildId: string): Promise<DeliveryBuildRow | null>;
  readJar(jarPath: string): Promise<Buffer | null>;
  projectForRoot(rootBuildId: string): Promise<{ id: string; namespace: string; userId: string } | null>;
  project(projectId: string): Promise<{ id: string; namespace: string; userId: string; rootBuildId: string | null } | null>;
  datapackAssets(revisionId: string): Promise<DatapackAssetRow[]>;
  host(server: S, ctx: { rootBuildId: string | null; buildId?: string | null }): DeliveryHost;
  storeResult(jobId: string, result: Record<string, unknown>): Promise<void>;
  audit(userId: string, action: string, detail: string): Promise<void>;
  installRow?(u: InstallRowUpdate): Promise<void>;
  /** Mod Packs: the OWNER's stored pack version, opened and verified (sha256, manifest, pack + version id). */
  modpack?(userId: string, ref: PackRef): Promise<{ ok: true; manifest: NxPack; archive: Map<string, Buffer> } | { ok: false; error: string }>;
  noRetry(jobId: string): Promise<void>;
};

export class DeliveryJobError extends Error {}

/** Final install-row state for a finished delivery (pure). */
export function installRowUpdate(p: DeliveryPayload, r: DeliveryResult, jarName: string | null): InstallRowUpdate | null {
  if (!p.serverModId) return null;
  const err = `${r.outcome === "rolled_back" ? "Rolled back: " : r.outcome === "rollback_incomplete" ? "Rollback incomplete: " : "Not delivered: "}${r.error ?? "failed"}`.slice(0, 900);
  if (r.ok) {
    if (p.op === "uninstall") return { kind: "removed", serverModId: p.serverModId };
    return { kind: "delivered", serverModId: p.serverModId, buildId: p.buildId!, jarName };
  }
  // refused / rolled back: the server is as it was, so the row is too. Incomplete rollback: the row says FAILED.
  if (r.outcome !== "rollback_incomplete" && p.prev) return { kind: "restore", serverModId: p.serverModId, prev: p.prev, error: err };
  return { kind: "failed", serverModId: p.serverModId, error: err };
}

async function refuse<S extends DeliveryServerRow>(job: DeliveryJob, deps: DeliveryJobDeps<S>, p: DeliveryPayload | null, msg: string): Promise<never> {
  await deps.noRetry(job.id);
  if (p?.serverModId && p.prev) await deps.installRow?.({ kind: "restore", serverModId: p.serverModId, prev: p.prev, error: `Not delivered: ${msg}`.slice(0, 900) }).catch(() => {});
  else if (p?.serverModId) await deps.installRow?.({ kind: "failed", serverModId: p.serverModId, error: `Not delivered: ${msg}`.slice(0, 900) }).catch(() => {});
  throw new DeliveryJobError(`cyrus delivery: ${msg}`);
}

export async function runDeliveryJob<S extends DeliveryServerRow>(job: DeliveryJob, deps: DeliveryJobDeps<S>): Promise<DeliveryResult> {
  const p = readDeliveryPayload(job.payload);
  if (!p || !job.serverId) return refuse(job, deps, p, "bad payload");
  if (deps.env[DELIVERY_FLAG] !== "1") return refuse(job, deps, p, `Cyrus delivery is switched off (${DELIVERY_FLAG} is not 1); nothing was changed`);
  const server = await deps.server(job.serverId);
  if (!server) return refuse(job, deps, p, `server ${job.serverId} not found`);
  if (p.requestedBy && p.requestedBy !== server.userId) return refuse(job, deps, p, "the request does not come from the server's owner");
  let result: DeliveryResult;
  let jarName: string | null = null;
  if (p.op === "uninstall") {
    const proj = await deps.project(p.projectId!);
    if (!proj || proj.userId !== server.userId) return refuse(job, deps, p, "the mod belongs to another account");
    result = await uninstallMod(server.id, proj.id, deps.host(server, { rootBuildId: proj.rootBuildId }), { restartPolicy: p.restartPolicy, acknowledge: p.acknowledge });
  } else if (p.op === "deliver") {
    const b = await deps.build(p.buildId!);
    if (!b || b.status !== "succeeded" || !b.jarPath) return refuse(job, deps, p, "the build has no finished plugin");
    if (b.userId !== server.userId) return refuse(job, deps, p, "the build belongs to another account");
    const root = b.rootBuildId ?? b.id;
    const proj = await deps.projectForRoot(root);
    if (proj && proj.userId !== server.userId) return refuse(job, deps, p, "the mod belongs to another account");
    const jar = await deps.readJar(b.jarPath).catch(() => null);
    const revId = (b.result as { assets?: { revisionId?: string | null } } | null)?.assets?.revisionId ?? null;
    const dpRows = revId ? await deps.datapackAssets(revId) : [];
    const rel = releaseFromBuild(b, jar, { project: proj ? { id: proj.id, namespace: proj.namespace } : null, datapackAssets: dpRows });
    if (!rel.ok) return refuse(job, deps, p, rel.error);
    jarName = b.jarName;
    result = await deliverMod(server.id, rel.release, deps.host(server, { rootBuildId: root, buildId: b.id }), { restartPolicy: p.restartPolicy, acknowledge: p.acknowledge });
    result.notes.unshift(...rel.notes);
  } else if (p.op === "modpack_install") {
    if (!deps.modpack) return refuse(job, deps, p, "this worker cannot read Mod Packs");
    // the store is per account: only the server owner's packs can be opened at all
    const pk = await deps.modpack(server.userId, p.pack!);
    if (!pk.ok) return refuse(job, deps, p, pk.error);
    const acked = new Set(p.acknowledge ?? []);
    const open = pk.manifest.conflicts.open.map((o) => o.findingId).filter((id) => !acked.has(id));
    if (open.length) return refuse(job, deps, p, `${open.length} open warning(s) of the pack were not acknowledged (${open.slice(0, 3).join(", ")}); nothing was changed`);
    result = await deliverModPack(server.id, { manifest: pk.manifest, archive: pk.archive }, deps.host(server, { rootBuildId: null }), { restartPolicy: p.restartPolicy, acknowledge: p.acknowledge });
  } else {
    result = await uninstallModPack(server.id, p.packId!, deps.host(server, { rootBuildId: null }), { restartPolicy: p.restartPolicy, acknowledge: p.acknowledge });
  }
  await deps.storeResult(job.id, compactResult(result)).catch((e) => console.error("[cyrus-delivery] result not stored", e));
  const row = installRowUpdate(p, result, jarName);
  if (row) await deps.installRow?.(row).catch((e) => console.error("[cyrus-delivery] install row not updated", e));
  // r40: the person hears the outcome (bell / email per their preferences; off unless CYRUS_NOTIFY=1, never throws)
  notifyInstallResult({ userId: server.userId, jobId: job.id, ok: result.ok, name: jarName ?? (p.packId ? `Mod Pack ${p.packId}` : "Your mod"), server: (server as { label?: string | null; hostname?: string }).label || (server as { hostname?: string }).hostname || "your server", restartRequired: false, reason: result.ok ? null : `${result.outcome.replace(/_/g, " ")}${result.error ? `: ${result.error}` : ""}`.slice(0, 200) });
  await deps.audit(server.userId, result.ok ? "cyrus.delivery.ok" : "cyrus.delivery.failed", `${server.id} job=${job.id} ${result.op} ${result.outcome} ${result.failedStep ?? ""} ${result.error ?? ""}`.slice(0, 900)).catch(() => {});
  // r38: install.result / delivery.rolledback webhooks (no-op unless CYRUS_API_V1_WEBHOOKS)
  await (await import("../api/v1/emit")).emitDeliveryResult({ userId: server.userId, jobId: job.id, result }).catch(() => {});
  if (!result.ok) { await deps.noRetry(job.id); throw new DeliveryJobError(`Cyrus delivery ${result.outcome}: ${result.error ?? "failed"}`); }
  return result;
}
  return transaction({
    serverId, op: "modpack_uninstall", subject: { packId }, host, label: `modpack-${packId}-uninstall`, opts,
    prepare: async (_session, steps) => timed({ steps, host }, "preflight", async () => {
      if (!/^mp_[A-Za-z0-9]{12}$/.test(packId)) throw new Refusal("preflight", "bad pack id");
      if (!switches(env).modpacks) throw new Refusal("preflight", "Mod Pack installs are switched off (CYRUS_MODPACK_INSTALL_REAL is not 1); nothing was changed");
      if (!host.modpackPlacer) throw new Refusal("preflight", "this host cannot place Mod Pack members");
      return { body: (t: Txn) => modpackBody(t, packId, false, (fs) => uninstallModPackUnit({ packId, base: t.session.base, deps: { fs, placer: host.modpackPlacer!(fs, t.session, packId) } }), [], true) };
    }, () => "ok"),
  });
}

async function modpackBody(t: Txn, packId: string, needsLoader: boolean, run: (fs: JournalFs) => Promise<UnitResult>, pluginNames: string[], uninstall = false): Promise<BodyOut> {
  const dep = packDependent(packId);
  let managedChanged = false;
  const expect: string[] = [];
  if (needsLoader) {
    await timed(t, "managed", async () => {
      t.refsTouched = true;
      const e = await t.host.managed.ensure({ serverId: t.serverId, key: PACK_LOADER_KEY, mcVersion: t.session.mcVersion ?? "", dependent: dep, fs: t.jfs });
      if (!e.ok) throw new Error(e.error);
      managedChanged = e.action === "installed" || e.action === "upgraded";
      expect.push(e.pluginName);
      return e.action;
    }, (v) => v);
  } else skip(t, "managed", "no resource packs");
  const unit = await timed(t, "place", async () => {
    const u = await run(t.jfs);
    if (!u.ok) throw new Error(`Mod Pack ${u.step}: ${u.error}`);
    return u;
  }, (u) => `${u.ok ? u.action : ""}: ${u.ok ? u.changed.slice(0, 6).join(", ") : ""}`);
  if (uninstall) {
    await timed(t, "managed", async () => { t.refsTouched = true; const r = await t.host.managed.release({ serverId: t.serverId, key: PACK_LOADER_KEY, dependent: dep, fs: t.jfs }); if (!r.ok) throw new Error(r.error); if (r.action === "removed") managedChanged = true; return r.action; }, (v) => v);
  }
  const u = unit as Extract<UnitResult, { ok: true }>;
  const datapacks = (u.record?.files ?? []).filter((f) => f.path.includes("/datapacks/")).map((f) => datapackId(f.path.slice(f.path.lastIndexOf("/") + 1)));
  // A Mod Pack's data packs may carry registry content or world generation the unit cannot tell apart: treated as
  // restart content (conservative), and the server must come up after it.
  const changed = u.action !== "unchanged";
  return {
    apply: { jarChanged: u.restartRequired, managedChanged, datapacks: datapacks.map(() => ({ changed, apply: "restart" as const, worldgen: false })), modelsChanged: false, managedConfigChanged: false, loaderChanged: needsLoader && changed },
    record: null, outcome: uninstall ? "uninstalled" : u.action === "updated" ? "updated" : "delivered", unchanged: !changed && !managedChanged,
    expect: { plugins: uninstall ? [] : [...expect, ...pluginNames], datapacks: uninstall ? [] : datapacks, worldgen: false },
  };
}

// ------------------------------------------------------------------------------------------------ Config Studio (values only)

/**
 * Deliver new SETTINGS of an installed Cyrus mod: merge the changed values into the server's current config file
 * (comments, unknown keys and the owner's own edits to other keys stay), then apply as the settings declare: the mod's
 * reload command over the console (a failing reply rolls back and reloads the old file), a restart + health check, or
 * nothing (live). Same transaction as every delivery (journal, recover check, rollback). OFF unless CYRUS_DELIVERY=1
 * AND CYRUS_CONFIG_STUDIO=1. No jar, no pack, no model call.
 */
export async function deliverConfig(serverId: string, rel: ConfigRelease, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
  const env = host.env ?? process.env;
  const subject = { projectId: rel.projectId, revisionId: rel.revisionId };
  if (env[CONFIG_STUDIO_FLAG] !== "1") {
    const at = (host.now ?? (() => new Date()))().toISOString();
    return { ok: false, outcome: "refused", op: "config", serverId, subject, steps: [], notes: [], error: "the Config Studio is switched off (CYRUS_CONFIG_STUDIO is not 1); nothing was changed", startedAt: at, finishedAt: at };
  }
  return transaction({
    serverId, op: "config", subject, host, label: `config-${rel.projectId}`, opts,
    prepare: async (session, steps) => timed({ steps, host }, "preflight", async () => {
      if (!/^[A-Za-z0-9_-]{1,64}$/.test(rel.projectId)) throw new Refusal("preflight", "bad project id; nothing was changed");
      if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(rel.pluginName)) throw new Refusal("preflight", "bad plugin name; nothing was changed");
      const v = validateConfigSpec(rel.spec);
      if (!v.ok) throw new Refusal("preflight", `the settings schema is invalid (${v.errors[0]?.message}); nothing was changed`);
      const spec = v.spec;
      const known = new Set(spec.params.map((p) => p.key));
      const bad = rel.changed.filter((k) => !known.has(k));
      if (bad.length) throw new Refusal("preflight", `${bad[0]} is not a setting of this mod; nothing was changed`);
      const chk = checkValues(spec, Object.fromEntries(rel.changed.map((k) => [k, rel.values[k]])), "strict");
      if (!chk.ok) throw new Refusal("preflight", `${chk.errors[0].message}; nothing was changed`);
      // the mod must be installed (its plugin enabled on the last boot or its jar present)
      const ro = host.readOnly?.(session) ?? session.fs;
      const inv = await scanServer(ro, { base: session.base });
      const names = inv.plugins.map((p) => p.descriptor?.name?.toLowerCase()).filter(Boolean);
      if (!names.includes(rel.pluginName.toLowerCase())) throw new Refusal("preflight", `${rel.pluginName} is not installed on this server; nothing was changed`);
      const target = `${session.base}/plugins/${rel.pluginName}/${spec.file}`;
      const prev = readRecord(await session.fs.readFile(recordPath(rel.projectId), 1024 * 1024));
      return { body: (t: Txn) => configBody(t, rel, spec, chk.values, target, prev) };
    }, () => "settings checked; the mod is installed"),
  });
}

async function configBody(t: Txn, rel: ConfigRelease, spec: ConfigSpec, values: ConfigValues, target: string, prev: DeliveryRecord | null): Promise<BodyOut> {
  const { jfs } = t;
  let changed = false, sha = "";
  await timed(t, "place", async () => {
    const cur = await jfs.readFile(target, 512 * 1024);
    const want = Object.fromEntries(rel.changed.map((k) => [k, values[k]]));
    let text: string;
    if (cur) {
      const w = writeValues(spec, cur.toString("utf8"), want);
      if (!w.ok) throw new Error(`the server's ${spec.file} could not be updated: ${w.errors[0].message}`);
      text = w.text;
    } else text = renderConfigYml(spec, values, [`${rel.pluginName} configuration (written by the Cyrus Config Studio).`]);
    const buf = Buffer.from(text, "utf8");
    sha = sha256(buf);
    if (cur && cur.equals(buf)) return `${spec.file} already has these values`;
    await jfs.mkdirp(target.slice(0, target.lastIndexOf("/")));
    await jfs.writeFile(`${target}.nxeon-part`, buf);
    await jfs.rename(`${target}.nxeon-part`, target);
    const back = await jfs.readFile(target, 512 * 1024);
    if (!back || sha256(back) !== sha) throw new Error(`${spec.file} does not verify after writing it`);
    changed = true;
    return `${spec.file}: ${rel.changed.length} setting(s) written`;
  }, (v) => v);
  let record: DeliveryRecord | null = prev;
  if (prev && changed) {
    record = { ...prev, config: { target, sha256: sha, revisionId: rel.revisionId, deliveredAt: (t.host.now ?? (() => new Date()))().toISOString() } };
    await timed(t, "record", async () => { const rp = recordPath(rel.projectId); await jfs.writeFile(`${rp}.part`, Buffer.from(JSON.stringify(record, null, 2) + "\n")); await jfs.rename(`${rp}.part`, rp); return rp; }, (v) => v);
  } else skip(t, "record", prev ? "nothing changed" : "the mod was not installed by Cyrus delivery: no delivery record to update");
  const applies = appliesFor(spec, rel.changed).applies;
  return {
    apply: { jarChanged: false, managedChanged: false, datapacks: [], modelsChanged: false, managedConfigChanged: false, loaderChanged: false, config: { changed, applies: applies === "none" ? "live" : applies, ...(spec.reload ? { reloadCommand: spec.reload.command } : {}) } },
    record, outcome: "updated", unchanged: !changed,
    expect: { plugins: [rel.pluginName], datapacks: [], worldgen: false },
  };
}
