};

/** Config Studio: one values-only delivery. The values are merged into the server's CURRENT file (owner edits to other keys stay). */
export type ConfigRelease = {
  projectId: string;
  revisionId: string;
  pluginName: string;
  spec: import("../config/spec").ConfigSpec;
