export type PreviewResult = { configYml: string; patch: Patch; applies: string; errors: ValueIssue[]; warnings: ValueIssue[]; written: string[]; values?: ConfigValues; /** config.yml lines removed (-) / added (+), in file order */ lines?: { sign: "-" | "+"; text: string }[] };

/** What a save WOULD write (the diff drawer): no write. */
export async function previewConfig(deps: ConfigServiceDeps, userId: string, rootBuildId: string, values: Record<string, unknown>): Promise<PreviewResult> {
  const { src, schema, vrows } = await context(deps, userId, rootBuildId);
  return computeSave(schema.spec, src, vrows, values);
}

function computeSave(spec: ConfigSpec | null, src: ConfigSource, vrows: ValuesRow[], values: Record<string, unknown>): PreviewResult {
  if (!spec) throw new ConfigError(409, "no_settings", "This mod has no settings Cyrus can edit.");
  const shipped = src.configYml ? readValues(spec, src.configYml).values : defaultsOf(spec);
  const last = vrows[vrows.length - 1];
  const current = last ? checkValues(spec, last.values, "clamp", shipped).values : shipped;
  const chk = checkValues(spec, values, "strict", current);
  if (!chk.ok) return { configYml: "", patch: [], applies: "none", errors: chk.errors, warnings: chk.warnings, written: [] };
  const patch = diffValues(spec, current, chk.values);
  const baseText = last?.configYml || src.configYml || "";
  let text: string;
  let written: string[] = [];
  if (baseText) {
    const w = writeValues(spec, baseText, Object.fromEntries(patch.map((p) => [p.key, p.to])));
    if (!w.ok) return { configYml: "", patch, applies: "none", errors: w.errors, warnings: chk.warnings, written: [] };
    text = w.text; written = w.written;
  } else { text = renderConfigYml(spec, chk.values, [`${src.pluginName ?? "Mod"} configuration (written by the Cyrus Config Studio).`]); written = patch.map((p) => p.key); }
  return { configYml: text, patch, applies: appliesFor(spec, patch.map((p) => p.key)).applies, errors: [], warnings: chk.warnings, written, values: chk.values, lines: lineChanges(baseText, text) };
}

/** The lines a values-only write changed (it replaces value spans or inserts lines; nothing moves). */
export function lineChanges(before: string, after: string): { sign: "-" | "+"; text: string }[] {
  const a = before.split("\n"), b = after.split("\n");
  const out: { sign: "-" | "+"; text: string }[] = [];
  let i = 0, j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i] === b[j]) { i++; j++; continue; }
    // an inserted run: b[j..] until a[i] reappears
    const k = i < a.length ? b.indexOf(a[i], j) : -1;
    if (k > j && b.slice(j, k).every((l) => !a.slice(i).includes(l))) { for (; j < k; j++) out.push({ sign: "+", text: b[j] }); continue; }
    if (i < a.length) out.push({ sign: "-", text: a[i++] });
    if (j < b.length) out.push({ sign: "+", text: b[j++] });
    if (out.length > 200) break;
  }
