"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { useInstallPlan } from "@/components/cyrus/lifecycle/useInstallPlan";

/**
 * NxLabs "Install on my server" for a Cyrus mod (own mods, or a PUBLISHED version of someone
 * else's): the same install plan the studio shows (lib/cyrus/lifecycle/install-plan.ts), in
 * portal theme tokens (dark + light), portalled to <body>.
 */
export function CyrusInstallButton({ buildId, label = "Install on my server", className }: { buildId: string; label?: string; className?: string }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button type="button" onClick={() => setOpen(true)} className={className ?? "inline-flex items-center justify-center gap-1.5 rounded-[11px] border border-white/20 bg-white/[0.07] px-3.5 py-2 text-[12.5px] font-semibold text-white transition hover:bg-white/[0.12]"}>
        <Icon name="server" size={13} tone="inherit" /> {label}
      </button>
      {open && <CyrusInstallDialog buildId={buildId} onClose={() => setOpen(false)} />}
    </>
  );
}

export function CyrusInstallDialog({ buildId, onClose }: { buildId: string; onClose: () => void }) {
  const p = useInstallPlan(buildId);
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => setHost(document.body), []);
  useEffect(() => {
    const k = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onClose]);
  if (!host) return null;
  const c = p.chosen;
  return createPortal(
    <div className="fixed inset-0 z-[95] grid place-items-center bg-black/55 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label="Install on my server" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="flex max-h-[calc(100dvh-32px)] w-full max-w-[560px] flex-col overflow-hidden rounded-[17px] border border-rim-hi bg-surface text-tx shadow-2xl" data-testid="cyrus-install-dialog">
        <div className="flex items-start gap-3 border-b border-rim-hi p-5 pb-4">
          <div className="min-w-0 flex-1">
            <h3 className="text-[16px] font-extrabold">{p.done ? (p.done.queued ? "Install queued" : "Installed") : "Install on my server"}</h3>
            {!p.done && <p className="mt-1 text-[12px] text-tx-dim">We check the server first, back up what we replace, and roll back if anything fails.</p>}
          </div>
          <button type="button" onClick={onClose} aria-label="Close" className="rounded-[9px] p-1.5 text-tx-dim hover:bg-well hover:text-tx"><Icon name="xcircle" size={16} tone="inherit" /></button>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto p-5 pt-4">
          {p.done ? (
            <div className="flex flex-col items-start gap-3">
              <p className="text-[13.5px] font-bold text-mint">{p.done.queued ? `Queued for ${p.done.serverName}.` : `It's on ${p.done.serverName}.`}</p>
              <p className="text-[12.5px] leading-relaxed text-tx-dim">
                {p.done.restarted ? "The server is restarting to load it." : p.done.restartNote ?? (c?.plan.restart === "hot" ? "It loads on its own." : "Restart the server to load it.")} We watch the log after the start and warn you if it fails to load.
              </p>
              {c && <Link href={`/dashboard/servers/${c.server.id}?tab=mods`} className="btn-primary text-[12.5px]">Open the Mods tab</Link>}
            </div>
          ) : (
            <>
              {!p.plans && !p.loadErr && <p className="flex items-center gap-2 text-[12.5px] text-tx-dim" role="status"><Icon name="refresh" size={12} tone="inherit" className="animate-spin" /> Checking your servers…</p>}
              {p.loadErr && <p className="text-[12.5px] text-rose" role="alert">{p.loadErr}</p>}
              {p.plans && p.plans.length === 0 && (
                <div className="flex flex-col items-start gap-2">
                  <p className="text-[13.5px] font-bold">You don&apos;t have a Minecraft server yet</p>
                  <p className="text-[12.5px] text-tx-dim">Cyrus mods are Paper plugins. Start a Paper server on Nxeon, or download the .jar for your own.</p>
                  <Link href="/dashboard/deploy?product=game" className="btn-primary text-[12.5px]">Get a Minecraft server</Link>
                </div>
              )}
              {p.plans && p.plans.length > 0 && (
                <div className="flex flex-col gap-3">
                  <div className="flex flex-col gap-1.5" role="radiogroup" aria-label="Server">
                    {p.plans.map(({ server: s, plan }) => (
                      <label key={s.id} className={"flex cursor-pointer items-center gap-3 rounded-[12px] border px-3 py-2.5 transition " + (p.sel === s.id ? "border-violet/60 bg-violet/[0.08]" : "border-rim-hi bg-well hover:border-violet/35")}>
                        <input type="radio" name="cy-install-srv" className="sr-only" checked={p.sel === s.id} onChange={() => p.setSel(s.id)} />
                        <span className={"h-2 w-2 flex-none rounded-full " + (s.status === "RUNNING" ? "bg-mint" : "bg-tx-faint")} aria-hidden />
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-[13px] font-bold">{s.name}</span>
                          <span className="block text-[11.5px] text-tx-faint">{cap(s.variant)}{s.version ? ` ${s.version}` : ""} · {s.status === "RUNNING" ? "online" : "stopped"}{plan.op === "update" ? " · has another version" : plan.op === "none" ? " · already has this version" : ""}</span>
                        </span>
                        <span className={"flex-none rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + (plan.blockers.length ? "border-rose/40 bg-rose/10 text-rose" : plan.op === "none" ? "border-rim-hi text-tx-dim" : plan.warnings.length ? "border-amber/45 bg-amber/[0.08] text-amber" : "border-mint/40 bg-mint/10 text-mint")}>
                          {plan.blockers.length ? "Can't install" : plan.op === "none" ? "Installed" : plan.warnings.length ? `${plan.warnings.length} to confirm` : "Ready"}
                        </span>
                      </label>
                    ))}
                  </div>
                  {c && c.plan.blockers.length > 0 && (
                    <ul className="flex flex-col gap-1.5 rounded-[12px] border border-rose/40 bg-rose/[0.07] p-3 text-[12.5px] leading-relaxed text-rose">
                      {c.plan.blockers.map((b) => <li key={b} className="flex gap-2"><Icon name="xcircle" size={13} tone="inherit" className="mt-0.5 flex-none" />{b}</li>)}
                    </ul>
                  )}
                  {c && !c.plan.blockers.length && c.plan.op !== "none" && (
                    <>
                      {c.plan.warnings.length > 0 && (
                        <fieldset className="flex flex-col gap-2 rounded-[12px] border border-amber/45 bg-amber/[0.07] p-3">
                          <legend className="px-1 text-[10.5px] font-bold uppercase tracking-[0.12em] text-amber">Confirm before installing</legend>
                          {c.plan.warnings.map((w) => (
                            <label key={w.id} className="flex cursor-pointer gap-2.5 text-[12.5px] leading-relaxed text-tx">
                              <input type="checkbox" className="mt-1 flex-none accent-violet-500" checked={p.acked.includes(w.id)} onChange={() => p.toggleAck(w.id)} />
                              <span>{w.text}</span>
                            </label>
                          ))}
                        </fieldset>
                      )}
                      <ol className="flex flex-col gap-1.5 text-[12.5px] leading-relaxed text-tx-dim">
                        {c.plan.steps.map((st, i) => (
                          <li key={st.id} className="flex gap-2.5"><span className="mt-0.5 grid h-[18px] w-[18px] flex-none place-items-center rounded-full border border-violet/50 text-[10px] font-bold text-violet">{i + 1}</span><span>{st.text}</span></li>
                        ))}
                      </ol>
                      <p className="text-[12px] text-tx-dim">{c.plan.players.needed ? c.plan.players.text : "Server only: players join with a normal, unmodded game."}</p>
                      <p className="text-[11.5px] leading-relaxed text-tx-faint">{c.plan.backupNote} {c.plan.rollbackNote}</p>
                      {c.server.status === "RUNNING" && c.plan.restart === "required" && (
                        <label className="flex cursor-pointer gap-2.5 text-[12.5px] text-tx">
                          <input type="checkbox" className="mt-1 accent-violet-500" checked={p.restart} onChange={(e) => p.setRestart(e.target.checked)} />
                          <span><strong>Restart when it&apos;s in place</strong> so the mod loads.</span>
                        </label>
                      )}
                    </>
                  )}
                  {!p.installsLive && <p className="text-[12px] text-amber">One-click mod changes are paused right now.</p>}
                  {p.err && <p className="text-[12.5px] text-rose" role="alert">{p.err}</p>}
                </div>
              )}
            </>
          )}
        </div>

        {!p.done && p.plans && p.plans.length > 0 && (
          <div className="flex flex-wrap justify-end gap-2 border-t border-rim-hi px-5 py-3">
            <button type="button" onClick={onClose} className="btn-ghost text-[12.5px]">Cancel</button>
            <button type="button" onClick={() => void p.submit()} disabled={!p.ready || p.busy} className="btn-primary text-[12.5px] disabled:opacity-50">
              {p.busy ? "Installing…" : c?.plan.op === "update" ? "Switch to this version" : "Install"}
            </button>
          </div>
        )}
      </div>
    </div>,
    host,
  );
}

const cap = (s: string | null) => (s ? s[0].toUpperCase() + s.slice(1) : "");
"use client";

// Install a built Cyrus plugin on one of the account's Paper/Purpur servers through the install
// plan (lib/actions-cyrus-lifecycle.ts installCyrusMod). Portalled to <body> with the token
// modal's look (.cy-tokens / .cy-modal in app/dashboard/cyrus/cyrus.css; .cy-lc-* added there).
import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { useInstallPlan } from "@/components/cyrus/lifecycle/useInstallPlan";
import { CyIcon, NeonDefs } from "./icons";
import { InstallReport } from "@/components/cyrus/bridge/InstallReport";

export function Modal({ title, sub, onClose, children, wide }: { title: string; sub?: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { window.removeEventListener("keydown", k); document.body.style.overflow = prev; };
  }, [onClose]);
  // Portalled to <body> so it sits above the portal's own top bar; .cy-tokens carries the theme.
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => setHost(document.body), []);
  if (!host) return null;
  return createPortal(
    <div className="cy-tokens cy-modal-back" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <NeonDefs />
      <div className={`cy-modal ${wide ? "wide" : ""}`}>
        <div className="cy-modal-h">
          <div className="flex min-w-0 flex-col gap-1">
            <h2>{title}</h2>
            {sub && <p>{sub}</p>}
          </div>
          <button type="button" className="cy-ib ml-auto" onClick={onClose} aria-label="Close"><CyIcon name="x" size={14} /></button>
        </div>
        {children}
      </div>
    </div>,
    host,
  );
}

export function InstallModal({ build, servers, onClose, onDone }: { build: ModBuildView; servers: MbServer[]; onClose: () => void; onDone: () => void }) {
  // Cyrus lifecycle (2026-10-08): the dialog shows the install PLAN for each server
  // (lib/cyrus/lifecycle/install-plan.ts): version check, what happens step by step, backup and
  // rollback, players' side, and every warning needs a tick before Install is enabled.
  const p = useInstallPlan(build.id, build.lastInstall?.serverId ?? null);
  const { chosen, done } = p;
  // r38: the pre-install conflict report (incl. duplicates from the Mods tab) for the chosen server; off = never blocks
  const [reportBlocked, setReportBlocked] = useState(false);
  const told = useRef(false);
  useEffect(() => {
    if (done && !told.current) { told.current = true; onDone(); }
  }, [done, onDone]);

  if (done) {
    const queued = !!done.queued;
    return (
      <Modal title={queued ? "Install queued" : "Installed"} onClose={onClose}>
        <div className="cy-done">
          <span className="cy-done-orb"><CyIcon name="check" size={22} strokeWidth={2.4} /></span>
          <p className="cy-done-t">{queued ? `${build.jarName} is queued for ${done.serverName}.` : `${build.jarName} is on ${done.serverName}.`}</p>
          <p className="cy-sub max-w-[46ch] text-center">
            {done.restarted ? "The server is restarting now. Your mod loads as soon as it's back up (usually under a minute)."
              : done.restartNote ? done.restartNote
              : chosen?.plan.restart === "hot" ? "It loads on its own, no restart needed."
              : "Restart the server to load the mod. Paper doesn't load new plugins while it's running."}
            {(done.replaced?.length ?? 0) > 0 && ` We replaced ${done.replaced!.join(", ")} and kept a backup of it.`}
            {" "}We watch the log after the start and warn you if it fails to load.
          </p>
          <p className="cy-sub max-w-[46ch] text-center">
            <b>Using its commands:</b> mod commands usually need operator permission. If Minecraft says &ldquo;Unknown or incomplete command&rdquo; for one of them, you are not an operator yet. Open your server&apos;s console and run <code>op YourMinecraftName</code>.
          </p>
          <div className="flex flex-wrap justify-center gap-2">
            <Link href={`/dashboard/servers/${chosen?.server.id}?tab=mods`} className="cy-btn primary">Open the Mods tab <CyIcon name="chevr" size={13} /></Link>
            <button type="button" className="cy-btn" onClick={onClose}>Done</button>
          </div>
        </div>
      </Modal>
    );
  }

  const none = p.plans && p.plans.length === 0 && servers.length === 0;
  return (
    <Modal title="Install to my server" sub="Checks the server first, backs up what it replaces, and rolls back if anything fails." onClose={onClose}>
      {!p.plans && !p.loadErr && <p className="cy-sub flex items-center gap-2" role="status"><i className="cy-spin" /> Checking your servers…</p>}
      {p.loadErr && <p role="alert" className="cy-err">{p.loadErr}</p>}
      {none || (p.plans && p.plans.length === 0) ? (
        <div className="cy-done">
          <span className="cy-done-orb dim"><CyIcon name="server" size={20} /></span>
          <p className="cy-done-t">You don&apos;t have a Minecraft server yet</p>
          <p className="cy-sub max-w-[40ch] text-center">Download the .jar and put it in any Paper server&apos;s plugins folder, or start a Paper server on Nxeon.</p>
          <Link href="/dashboard/deploy" className="cy-btn primary">Get a Minecraft server</Link>
        </div>
      ) : p.plans && (
        <>
          <div className="cy-srvs" role="radiogroup" aria-label="Server">
            {p.plans.map(({ server: s, plan }) => {
              const blocked = plan.blockers.length > 0 || plan.op === "none";
              return (
                <label key={s.id} className={`cy-srv ${p.sel === s.id ? "on" : ""} ${blocked ? "dim" : ""}`}>
                  <input type="radio" name="cy-srv" className="sr-only" checked={p.sel === s.id} onChange={() => p.setSel(s.id)} />
                  <span className={`cy-srv-dot ${s.status === "RUNNING" ? "up" : ""}`} />
                  <span className="flex min-w-0 flex-1 flex-col">
                    <b className="truncate">{s.name}</b>
