                      {plan.op === "update" ? " · has another version" : plan.op === "none" ? " · already has this version" : ""}
                    </span>
                  </span>
                  <span className={`cy-lc-pill ${plan.blockers.length ? "bad" : plan.warnings.length ? "warn" : "ok"}`}>{plan.blockers.length ? "Can't install" : plan.op === "none" ? "Installed" : plan.warnings.length ? `${plan.warnings.length} to confirm` : "Ready"}</span>
