              {chosen.plan.blockers.length === 0 && chosen.plan.op !== "none" && (
                <>
                  {chosen.plan.warnings.length > 0 && (
                    <fieldset className="cy-lc-list warn">
                      <legend>Confirm before installing</legend>
                      {chosen.plan.warnings.map((w) => (
                        <label key={w.id} className="cy-checkrow">
                          <input type="checkbox" checked={p.acked.includes(w.id)} onChange={() => p.toggleAck(w.id)} />
                          <span>{w.text}</span>
                        </label>
                      ))}
                    </fieldset>
                  )}
                  <ol className="cy-lc-steps" aria-label="What happens">
                    {chosen.plan.steps.map((st, i) => <li key={st.id}><span className="n">{i + 1}</span><span>{st.text}</span></li>)}
                  </ol>
                  {!chosen.plan.players.needed && <p className="cy-sub"><CyIcon name="check" size={12} /> Server only: players join with a normal, unmodded game.</p>}
                  <p className="cy-sub">{chosen.plan.backupNote} {chosen.plan.rollbackNote}</p>
                  {chosen.server.status === "RUNNING" && chosen.plan.restart === "required" && (
                    <label className="cy-checkrow">
                      <input type="checkbox" checked={p.restart} onChange={(e) => p.setRestart(e.target.checked)} />
                      <span><b>Restart the server when it&apos;s in place</b> so the mod loads. Players get a short warning first.</span>
                    </label>
                  )}
                </>
              )}
            </div>
          )}
          {chosen && chosen.plan.blockers.length === 0 && chosen.plan.op !== "none" ? <InstallReport buildId={build.id} serverId={chosen.server.id} onVerdict={setReportBlocked} /> : null}
          {!p.installsLive && <p className="cy-err">One-click mod changes are paused right now. Download the .jar to install it yourself.</p>}
          {p.err && <p role="alert" className="cy-err">{p.err}</p>}
          <div className="flex justify-end gap-2">
            <button type="button" className="cy-btn" onClick={onClose}>Cancel</button>
            <button type="button" className="cy-btn primary" disabled={!p.ready || p.busy || reportBlocked} onClick={() => void p.submit()}>
              {p.busy ? <i className="cy-spin" /> : <CyIcon name="server" size={14} />} {p.busy ? "Installing…" : chosen?.plan.op === "update" ? "Switch to this version" : "Install"}
            </button>
          </div>
        </>
      )}
    </Modal>
  );
}

const cap = (s: string | null) => (s ? s[0].toUpperCase() + s.slice(1) : "");

"use client";

// Shared state of the Cyrus install dialog (studio InstallModal and the NxLabs "Install on my
// server" button): the plans for each server (lib/cyrus/lifecycle/install-plan.ts), the chosen
// server, which warnings the customer ticked, the restart choice, and the submit.
import { useCallback, useEffect, useMemo, useState } from "react";
import { getCyrusInstallPlans, installCyrusMod, type CyrusInstallResult } from "@/lib/actions-cyrus-lifecycle";
import type { ServerPlan } from "@/lib/cyrus/lifecycle/server";

export function useInstallPlan(buildId: string, preferServerId?: string | null) {
  const [plans, setPlans] = useState<ServerPlan[] | null>(null);
  const [loadErr, setLoadErr] = useState<string | null>(null);
  const [installsLive, setInstallsLive] = useState(true);
  const [sel, setSel] = useState<string | null>(null);
  const [acked, setAcked] = useState<string[]>([]);
  const [restart, setRestart] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<CyrusInstallResult | null>(null);

  useEffect(() => {
    let live = true;
    getCyrusInstallPlans(buildId)
      .then((r) => {
        if (!live) return;
        if (r.error || !r.plans) return setLoadErr(r.error ?? "Couldn't check your servers.");
        setPlans(r.plans);
        setInstallsLive(r.installsLive !== false);
        const ok = r.plans.filter((p) => !p.plan.blockers.length && p.plan.op !== "none");
        setSel((preferServerId && r.plans.some((p) => p.server.id === preferServerId) ? preferServerId : null) ?? ok[0]?.server.id ?? r.plans[0]?.server.id ?? null);
      })
      .catch(() => live && setLoadErr("Couldn't check your servers."));
    return () => { live = false; };
  }, [buildId, preferServerId]);

  const chosen = useMemo(() => plans?.find((p) => p.server.id === sel) ?? null, [plans, sel]);
  useEffect(() => setAcked([]), [sel]);
  const toggleAck = useCallback((id: string) => setAcked((a) => (a.includes(id) ? a.filter((x) => x !== id) : [...a, id])), []);
  const ready = !!chosen && !chosen.plan.blockers.length && chosen.plan.op !== "none" && chosen.plan.warnings.every((w) => acked.includes(w.id)) && installsLive;

  const submit = useCallback(async () => {
    if (!chosen || !ready) return;
    setBusy(true);
    setErr(null);
    const r = await installCyrusMod(buildId, chosen.server.id, acked, { restart: restart && chosen.plan.restart === "required" }).catch(() => ({ error: "We couldn't reach Nxeon. Try again." }) as CyrusInstallResult);
    setBusy(false);
    if (r.error) setErr(r.error);
    else setDone(r);
  }, [buildId, chosen, ready, acked, restart]);

  return { plans, loadErr, installsLive, sel, setSel, chosen, acked, toggleAck, restart, setRestart, ready, busy, err, done, submit };
}
/**
 * The install plan a customer confirms before a Cyrus mod goes onto their server (PURE).
 * Everything comes from the game's GameSupport (path, packaging, restart, hot reload, which
 * side needs the files) plus the version check (./compat.ts). The SAME function runs in the
 * dialog and again on the server when the install is submitted, so a warning the customer
 * didn't tick can't be skipped by calling the API directly.
 */
import type { GameSupport } from "../games/support";
import { checkCompat, type CompatReason } from "./compat";
import { cyrusConfig } from "../config";

export type PlanServer = {
  id: string;
  name: string;
  /** Server game family matches the mod's game. */
  sameGame: boolean;
  /** Runs a loader/variant Cyrus mods can go on (Paper/Purpur for Minecraft). */
  variantOk: boolean;
  variantNote?: string;
  running: boolean;
  version: string | null;
  /** The mod's state on this server already (ServerMod.status), null = not installed. */
  existing: { status: string; buildId: string | null } | null;
};

export type PlanMod = {
  name: string;
  /** The build being installed. */
  buildId: string;
  /** Its target game version (ModBuild.mcVersion). */
  target: string;
  builtFor: string[];
  /** A real installer exists for this game's Cyrus mods (Minecraft today). */
  installable: boolean;
  safety: "pass" | "warn" | "block" | null;
};

export type InstallStep = { id: string; text: string };

export type InstallPlan = {
  serverId: string;
  /** install | update (same mod, other version) | none (already this version) */
  op: "install" | "update" | "none";
  /** Hard stops: install is refused while any is present. */
  blockers: string[];
  /** Need an explicit tick; `id` is what the confirm sends back. */
  warnings: { id: string; text: string }[];
  steps: InstallStep[];
  /** Players must install something on their own PC (side client/both). */
  players: { needed: boolean; text: string | null };
  restart: "required" | "hot" | "none";
  backupNote: string;
  rollbackNote: string;
};

export function buildInstallPlan(support: GameSupport, mod: PlanMod, s: PlanServer): InstallPlan {
  const blockers: string[] = [];
  const warnings: { id: string; text: string }[] = [];
  const g = support.name;
  if (!mod.installable) blockers.push(`One-click installs of Cyrus ${g} mods aren't available yet. Download the files and follow the steps on the mod page.`);
  if (!s.sameGame) blockers.push(`${s.name} isn't a ${g} server.`);
  else if (!s.variantOk) blockers.push(s.variantNote ?? `${s.name} runs a server type this mod can't load on.`);
  if (s.sameGame && !s.running) blockers.push("Start the server first: mods are installed onto the running server.");
  if (mod.safety === "block") blockers.push("This version failed the safety scan, so it can't be installed.");
  if (s.existing && !["INSTALLED", "FAILED", "REMOVED"].includes(s.existing.status)) {
    blockers.push(s.existing.status === "DISABLED" ? `${mod.name} is switched off on ${s.name}. Switch it on in the Mods tab first.` : `${mod.name} is busy on ${s.name} right now. Try again in a moment.`);
  }

  const compat = s.sameGame ? checkCompat({ support, serverVersion: s.version, target: mod.target, builtFor: mod.builtFor }) : null;
  for (const r of compat?.reasons ?? []) (r.level === "block" ? blockers.push(r.text) : warnings.push({ id: r.code, text: r.text }));
  if (mod.safety === "warn") warnings.push({ id: "safety-warn", text: "The safety scan left notes on this version (see the mod's Code tab). It was not blocked." });

  const side = support.install.side;
  const players = side === "server"
    ? { needed: false, text: null }
    : { needed: true, text: support.install.clientNote ?? `Players must also install ${mod.name} on their own PC, the same version as the server, or they won't be able to join.` };
  if (players.needed) warnings.push({ id: "players-must-install", text: `Players must also install this. ${players.text}` });

  const op: InstallPlan["op"] = s.existing?.status === "INSTALLED" ? (s.existing.buildId === mod.buildId ? "none" : "update") : "install";
  const restart: InstallPlan["restart"] = support.install.hotReload ? "hot" : support.install.needsRestart ? "required" : "none";
  const where = support.install.serverPath;
  const steps: InstallStep[] = [
    { id: "check", text: `Check ${s.name}: game version, ${support.loader.name}, free space.` },
    { id: "backup", text: op === "update" ? `Back up the current ${mod.name} file and its config.` : `Back up anything we would replace in ${where}.` },
    { id: "place", text: `Place ${mod.name} (${support.install.packaging}) in ${where}. Its existing config and data stay.` },
    restart === "hot"
      ? { id: "load", text: `${support.loader.name} loads it on its own, no restart.` }
      : { id: "load", text: "Restart the server to load it (we'll offer a restart when it's in place)." },
    { id: "verify", text: "Watch the log after the start: if it fails to load or the server keeps crashing, you get a warning and it can be switched off." },
  ];
  if (players.needed) steps.push({ id: "players", text: "Send your players the client install steps (on the mod page)." });

  return {
    serverId: s.id,
    op,
    blockers,
    warnings,
    steps,
    players,
    restart,
    backupNote: `Before anything changes, the file being replaced and the mod's config are copied to ${cyrusConfig().guest.modsBackupDir} on ${s.name} (the last 5 changes are kept).`,
    rollbackNote: "If writing the files fails, everything is put back as it was. If the new version misbehaves, roll back to any earlier version from the Mods tab.",
  };
}

/** Server-side gate: every warning must be acknowledged, no blocker may remain. */
export function confirmPlan(plan: InstallPlan, acked: string[]): { ok: true } | { ok: false; error: string } {
  if (plan.blockers.length) return { ok: false, error: plan.blockers[0] };
  const missing = plan.warnings.filter((w) => !acked.includes(w.id));
  if (missing.length) return { ok: false, error: `Please confirm: ${missing[0].text}` };
  return { ok: true };
}

export type { CompatReason };

