/** Balance warnings: a value outside `safe` (never an error). */
export function balanceWarnings(p: ConfigParam, v: ConfigValue): ValueIssue[] {
  if (!p.safe || !numeric(p)) return [];
  const vals = p.type === "range" ? (v as number[]) : [v as number];
  const u = p.unit ? ` ${p.unit}` : "";
  const out: ValueIssue[] = [];
  const lo = p.safe.min, hi = p.safe.max;
  if (lo !== undefined && vals.some((x) => x < lo)) out.push({ key: p.key, code: "below_balanced", message: `${p.label} ${fmt(p, v)} is below the balanced range (${lo}${u} or more)${p.safe.note ? `: ${p.safe.note}` : ""}` });
  if (hi !== undefined && vals.some((x) => x > hi)) out.push({ key: p.key, code: "above_balanced", message: `${p.label} ${fmt(p, v)} is above the balanced range (${hi}${u} or less)${p.safe.note ? `: ${p.safe.note}` : ""}` });
  return out;
}

/** Check one value: coerce, shape, hard limits (strict refuses, clamp clamps), step rounding, balance warnings. */
export function checkValue(p: ConfigParam, raw: unknown, mode: ValueMode = "strict"): CheckedValue {
  const bad = (code: string, message: string): CheckedValue => ({ ok: false, error: { key: p.key, code, message: `${p.label}: ${message}` } });
  let v = coerce(p, raw);
  if (p.type === "int" && isNum(v) && !Number.isInteger(v) && mode === "clamp") v = Math.round(v);
  const se = shapeError(p, v);
  if (se) return bad("bad_type", se);
  let clamped = false;
  const lim = (x: number) => {
    let y = x;
    if (p.min !== undefined && y < p.min) y = p.min;
    if (p.max !== undefined && y > p.max) y = p.max;
    if (y !== x) clamped = true;
    return y;
  };
  if (numeric(p)) {
    const vals = p.type === "range" ? [...(v as number[])] : [v as number];
    const out = vals.map((x) => {
      if (mode === "strict" && ((p.min !== undefined && x < p.min) || (p.max !== undefined && x > p.max))) return NaN;
      return round(lim(x), p.type === "int" ? Math.max(1, p.step ?? 1) : p.step);
    });
    if (out.some((x) => Number.isNaN(x))) return bad("outside_limits", `${fmt(p, v as ConfigValue)} is outside the allowed ${p.min ?? "-inf"}-${p.max ?? "inf"}${p.unit ? ` ${p.unit}` : ""}`);
    v = p.type === "range" ? out : out[0];
    if (p.type === "range" && (v as number[])[0] > (v as number[])[1]) return bad("bad_type", "the low end is above the high end");
  }
  if (p.type === "list" && p.item && (p.item.min !== undefined || p.item.max !== undefined)) {
    const it = p.item;
    const arr = (v as ScalarValue[]).map((x) => {
      if (!isNum(x)) return x;
      if (mode === "clamp") { const y = Math.min(it.max ?? Infinity, Math.max(it.min ?? -Infinity, x)); if (y !== x) clamped = true; return y; }
      return x;
    });
    for (const x of arr) { const e = cellError(it, x); if (e) return bad("outside_limits", `an item ${e}`); }
    v = arr;
  }
  if (p.type === "table") {
    const rows = (v as Record<string, ScalarValue>[]).map((row) => {
      const r: Record<string, ScalarValue> = {};
      for (const c of p.columns ?? []) {
        let x = row[c.key] ?? c.default;
        if (x === undefined) continue;
        if (isNum(x) && mode === "clamp") { const y = Math.min(c.max ?? Infinity, Math.max(c.min ?? -Infinity, x)); if (y !== x) clamped = true; x = y; }
        r[c.key] = x;
      }
      for (const [k, x] of Object.entries(row)) if (!(k in r) && !(p.columns ?? []).some((c) => c.key === k)) r[k] = x; // unknown columns are kept
      return r;
    });
    for (let i = 0; i < rows.length; i++) for (const c of p.columns ?? []) { if (rows[i][c.key] === undefined) continue; const e = cellError(c, rows[i][c.key]); if (e) return bad("outside_limits", `row ${i + 1} ${c.label} ${e}`); }
    v = rows;
  }
  return { ok: true, value: v as ConfigValue, clamped, warnings: balanceWarnings(p, v as ConfigValue) };
}

