    <main className="cfg-ws one"><section className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
      <div className="cys-empty" style={{ maxWidth: 460 }}><SI n="gauge" /><p><b>This mod has no settings Cyrus can edit yet.</b></p><p className="cys-hint">{view.notes[0] ?? "Ask Cyrus to make its numbers configurable in your next change."}</p></div>
    </section></main>
  );

  const groups = [...spec.groups].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  const ql = q.trim().toLowerCase();
  const shown = spec.params.filter((p) => (!ql || `${p.label} ${p.key} ${p.help ?? ""} ${p.tags.join(" ")}`.toLowerCase().includes(ql)) && (!group || ql || p.group === group));

  const openReview = async () => {
    setBusy(true);
    try { setReview(await api<Preview>({ method: "POST", body: { root: mod.rootId, action: "preview", values: Object.fromEntries(changedKeys.map((k) => [k, vals[k]])) } })); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const save = async () => {
    setBusy(true);
    try {
      const r = await api<{ seq: number; applies: string }>({ method: "POST", body: { root: mod.rootId, action: "save", values: Object.fromEntries(changedKeys.map((k) => [k, vals[k]])), expectedHeadId: view.headRevisionId } });
      toast(`Saved as revision ${r.seq}. ${r.applies === "reload" && spec.reload ? `Takes effect with ${spec.reload.command}.` : r.applies === "restart" ? "Takes effect after a server restart." : ""}`);
      setReview(null); await load();
    } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const undo = async (revisionId: string) => {
    setBusy(true);
    try { const r = await api<{ seq: number }>({ method: "POST", body: { root: mod.rootId, action: "revert", revisionId, expectedHeadId: view.headRevisionId } }); toast(`Undone as revision ${r.seq}.`); await load(); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const runCmd = async () => {
    if (!cmd.trim()) return;
    try {
      const r = await api<{ kind: "values"; edits: { key: string; value: ConfigValue }[]; summary: string[] } | { kind: "model"; reason: string }>({ method: "POST", body: { root: mod.rootId, action: "plan", text: cmd } });
      if (r.kind === "values") { setVals((o) => ({ ...o, ...Object.fromEntries(r.edits.map((e) => [e.key, e.value])) })); toast(r.summary.join("; ")); setCmd(""); }
      else toast(`Cyrus can't do that without the AI: ${r.reason}. Change it in the form or ask in a normal change.`, true);
    } catch (e) { toast((e as Error).message, true); }
  };

  return (
    <>
      {readOnly && <div className="cfg-ro"><SI n="phone" />Read only on a phone: open this page on a bigger screen to change settings.</div>}
      <main className="cfg-ws">
        <nav className="cfg-rail cys-panel cys-glass" aria-label="Setting groups">
          <button className={`cfg-g ${!group ? "on" : ""}`} onClick={() => setGroup(null)}>All settings<span className="n">{spec.params.length}</span></button>
          {groups.map((g) => (
            <button key={g.id} className={`cfg-g ${group === g.id ? "on" : ""}`} onClick={() => setGroup(g.id)}>
              {g.label}{spec.params.some((p) => p.group === g.id && changedKeys.includes(p.key)) && <span className="ch" aria-label="changed" />}
              <span className="n">{spec.params.filter((p) => p.group === g.id).length}</span>
            </button>
          ))}
          <div className="cfg-legend">
            <span className="cys-eyebrow">How changes apply</span>
            {spec.reload && <><Badge a="reload" />  <span>{spec.reload.command}, no restart</span></>}
            <Badge a="restart" /><span>Needs a server restart</span>
