  modBuild: { findMany(args: unknown): Promise<BuildLike[]> };
};

const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

export function deliveryRow(j: JobLike): DeliveryRow {
  const p = obj(j.payload);
  const r = obj(obj(p.result).cyrusDelivery);
  const rb = r.rollback ? obj(r.rollback) : null;
  return {
    jobId: j.id, serverId: j.serverId, createdAt: j.createdAt.toISOString(), jobStatus: j.status,
    op: typeof r.op === "string" ? r.op : (obj(p.cyrusDelivery).op as string) ?? null,
    outcome: typeof r.outcome === "string" ? r.outcome : null, ok: typeof r.ok === "boolean" ? r.ok : null,
    failedStep: typeof r.failedStep === "string" ? r.failedStep : null, error: typeof r.error === "string" ? r.error : null,
    steps: Array.isArray(r.steps) ? (r.steps as DeliveryRow["steps"]).slice(0, 40) : [],
    rollback: rb ? { ok: rb.ok === true, restored: Number(rb.restored ?? 0), removed: Number(rb.removed ?? 0), mismatches: Array.isArray(rb.mismatches) ? (rb.mismatches as string[]).slice(0, 10) : [], refs: String(rb.refs ?? "unchanged"), restarted: rb.restarted === true, healthOk: rb.health ? obj(rb.health).ok === true : null } : null,
    healthOk: r.health ? obj(r.health).ok === true : null,
    notes: Array.isArray(r.notes) ? (r.notes as string[]).slice(0, 12) : [],
    subject: Object.fromEntries(Object.entries(obj(r.subject)).filter(([, v]) => typeof v === "string")) as Record<string, string>,
  };
}

/** Aggregate stored flights per version (pure). Only completed flights (state done) count towards the rate. */
export function passRates(flights: { version: string; state: StoredFlight["state"]; verdict: StoredFlight["verdict"] }[]): PassRateRow[] {
  const m = new Map<string, PassRateRow>();
  for (const f of flights) {
    const r = m.get(f.version) ?? { version: f.version, flown: 0, passed: 0, failed: 0, incomplete: 0, notRun: 0, passRate: null };
    if (f.state === "done") { r.flown++; if (f.verdict === "passed") r.passed++; else if (f.verdict === "failed") r.failed++; else r.incomplete++; }
    else if (f.state === "not_run" || f.state === "gave_up") r.notRun++;
    m.set(f.version, r);
  }
  return [...m.values()].map((r) => ({ ...r, passRate: r.flown ? Math.round((r.passed / r.flown) * 1000) / 1000 : null })).sort((a, b) => b.version.localeCompare(a.version, undefined, { numeric: true }));
}

/**
 * `telemetry` (optional; nothing passes it yet): the mod health telemetry aggregates (k-anonymous rows only are shown,
 * see lib/cyrus/telemetry/aggregate.ts). Without it the report has no `health` key.
 */
export async function cyrusOpsReport(db: AdminDb, opts: { limit?: number; now?: Date; telemetry?: { enabled: boolean; rows: () => Promise<AggregateRow[]> }; library?: () => Promise<LibraryAdminView> } = {}): Promise<CyrusOpsReport> {
  const limit = Math.min(500, Math.max(1, opts.limit ?? 100));
  const jobs = await db.job.findMany({ where: { type: "GAME_MOD_SYNC", payload: { path: ["cyrusDelivery", "v"], equals: 1 } }, orderBy: { createdAt: "desc" }, take: limit, select: { id: true, serverId: true, createdAt: true, status: true, payload: true } });
  const builds = await db.modBuild.findMany({ where: { status: "succeeded" }, orderBy: { finishedAt: "desc" }, take: limit * 5, select: { id: true, mcVersion: true, cyrus: true } });
  const flights: FlightRow[] = [];
  const engines: EngineRow[] = [];
  for (const b of builds) {
    const c = obj(b.cyrus);
    const f = readStoredFlight(c.testFlight);
    if (f) flights.push({ buildId: b.id, mcVersion: b.mcVersion, state: f.state, verdict: f.verdict, label: f.label, checks: f.checks, reason: f.reason ?? null, at: f.at });
    const e: EngineRelease | null = readEngineRelease(c.engineRelease);
    if (e) engines.push({ buildId: b.id, mcVersion: b.mcVersion, engineId: e.id, recordedAt: e.recordedAt, prompt: e.prompts.base ?? null, scanner: e.scanner?.sha256?.slice(0, 12) ?? null, image: e.service?.image ?? null, unknown: e.unknown });
  }
  return {
    generatedAt: (opts.now ?? new Date()).toISOString(),
    deliveries: jobs.map(deliveryRow),
    flights: flights.slice(0, limit), engines: engines.slice(0, limit),
    passRates: passRates(flights.map((f) => ({ version: f.mcVersion, state: f.state, verdict: f.verdict }))),
    ...(opts.telemetry ? { health: opsTelemetryView(await opts.telemetry.rows(), { enabled: opts.telemetry.enabled, window: windowOf(opts.now ?? new Date()) }) } : {}),
    // a library read failure (tables not migrated yet) never breaks the ops report
    ...(opts.library ? { library: await opts.library().catch((e: unknown) => ({ error: String((e as Error)?.message ?? e).slice(0, 200) })) } : {}),
  };
}
