// Cyrus Config Studio: VALUE checking. Coercion from editor/YAML input, hard-limit checks (strict: refuse; clamp: what
// the generated runtime loader does), balance warnings (the `safe` range), defaults, display formatting. Pure.
import { CONFIG_LIMITS, cellError, numeric, paramByKey, shapeError, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues, type ScalarValue } from "./spec";

export type ValueMode = "strict" | "clamp";
export type ValueIssue = { key: string; code: string; message: string };
export type CheckedValue = { ok: true; value: ConfigValue; clamped: boolean; warnings: ValueIssue[] } | { ok: false; error: ValueIssue };

const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const round = (x: number, step?: number) => {
  if (!step) return Math.round(x * 1e6) / 1e6;
  const n = Math.round(x / step) * step;
  const d = (String(step).split(".")[1] ?? "").length;
  return Number(n.toFixed(Math.min(6, d)));
};

/** Text from a form field or a YAML scalar -> the param's value type (numbers from strings, "true"/"false"). */
export function coerce(p: Pick<ConfigParam, "type" | "item" | "columns" | "options">, raw: unknown): unknown {
  const num = (v: unknown) => (typeof v === "string" && /^\s*[-+]?(\d+(\.\d*)?|\.\d+)([eE][-+]?\d+)?\s*$/.test(v) ? Number(v) : v);
  const bool = (v: unknown) => (typeof v === "string" && /^(true|false|yes|no|on|off)$/i.test(v.trim()) ? /^(true|yes|on)$/i.test(v.trim()) : v);
  const cell = (type: string, v: unknown, options?: ConfigParam["options"]) => {
    if (type === "number" || type === "int") return num(v);
    if (type === "bool") return bool(v);
    if (type === "enum" && options?.some((o) => typeof o.value === "number")) return num(v);
    if (type === "enum" || type === "text" || type === "color" || type === "sound-ref" || type === "asset-ref") return typeof v === "number" || typeof v === "boolean" ? String(v) : v === null ? "" : v;
    return v;
  };
  switch (p.type) {
    case "number": case "int": case "duration": return num(raw);
    case "range": {
      if (typeof raw === "string") { const m = /^\s*(-?[\d.]+)\s*(?:-|to|\.\.)\s*(-?[\d.]+)\s*$/.exec(raw); if (m) return [Number(m[1]), Number(m[2])]; }
      return Array.isArray(raw) ? raw.map(num) : raw;
    }
    case "list": return Array.isArray(raw) ? raw.map((v) => cell(p.item?.type ?? "text", v, p.item?.options)) : raw;
    case "table": return Array.isArray(raw) ? raw.map((row) => (row && typeof row === "object" && !Array.isArray(row) ? Object.fromEntries(Object.entries(row as Record<string, unknown>).map(([k, v]) => { const c = p.columns?.find((x) => x.key === k); return [k, c ? cell(c.type, v, c.options) : v]; })) : row)) : raw;
    default: return cell(p.type, raw, p.options);
  }
}

