// Cyrus studios (R1b): the Prisma-backed StudioStore and the build-chain reader. SERVER ONLY. Cyrus tables through
// lib/cyrus/engine-core/store.ts, plus the ModBuild chain the studio lives on (read only). No auth / Nxeon imports, so
// scripts and DB tests can use it directly.
import { cyrusDb as db } from "../db";
import { readBuildAssets } from "../assets/sync";
import { addRevision, manifestOf, recordAsset, reserveIdentifier } from "../engine-core/store";
import { candidateKeyOf, candidateSummaryOf, soundCandidateOf } from "./marker";
import { readFile } from "node:fs/promises";
import { indexZip, readEntry } from "../inventory/zipread";
import type { ConfigSource } from "../config/service";
import type { ChainInfo, StudioStore } from "./service";

export const prismaStudioStore: StudioStore = {
  projectForRoot: (root) => db.cyrusProject.findUnique({ where: { rootBuildId: root } }),
  project: (id) => db.cyrusProject.findUnique({ where: { id } }),
  assets: (projectId) => db.cyrusProjectAsset.findMany({ where: { projectId }, orderBy: { createdAt: "asc" }, take: 2000 }),
  assetById: (id) => db.cyrusProjectAsset.findUnique({ where: { id } }),
  revisions: async (projectId) => (await db.cyrusRevision.findMany({ where: { projectId }, orderBy: { seq: "asc" } })).map((r) => ({ id: r.id, seq: r.seq, kind: r.kind, status: r.status, message: r.message, createdAt: r.createdAt, manifest: manifestOf(r), modBuildId: r.modBuildId })),
  addRevision: async (projectId, input) => { const r = await addRevision(projectId, input); return { id: r.id, seq: r.seq }; },
  recordAsset: async (projectId, a) => ({ id: (await recordAsset(projectId, a)).id }),
  reserve: async (projectId, kind, key) => ({ fullId: (await reserveIdentifier(projectId, kind, key)).fullId }),
};

/** The mod's build chain (ModBuild rows of the owner: the root and every build that names it). */
export async function chainOf(userId: string, rootBuildId: string): Promise<ChainInfo | null> {
  const rows = await db.modBuild.findMany({
    where: { userId, OR: [{ id: rootBuildId }, { rootBuildId }] },
    orderBy: { createdAt: "desc" }, take: 200,
    select: { id: true, rootBuildId: true, status: true, error: true, createdAt: true, mcVersion: true, pluginName: true, changeRequest: true, result: true },
  });
