  /** A client Idempotency-Key (the same key always answers with the same job). */
  idempotencyKey: string | null;
};
/** What the host's delivery answers: the job is QUEUED (the worker runs deliverConfig); poll /api/cyrus/delivery/v1/<jobId>. */
export type ConfigDeliverResult = { ok: boolean; outcome: string; error?: string; notes?: string[]; jobId?: string; reused?: boolean };''')
s=s.replace('''  deliver?: (i: ConfigDeliverInput) => Promise<{ ok: boolean; outcome: string; error?: string; notes?: string[] }>;''','''  deliver?: (i: ConfigDeliverInput) => Promise<ConfigDeliverResult>;''')
