new='''/** The setting keys a send must write: everything that differs from what the build shipped PLUS every key any studio revision up to this one touched (so a key set back to the shipped value still reaches a server that got the earlier value). */
export function keysToSend(spec: ConfigSpec, shipped: ConfigValues, values: ConfigValues, patches: readonly Patch[]): string[] {
  const touched = new Set<string>();
  for (const patch of patches) for (const op of patch) touched.add(op.key);
  return spec.params.filter((p) => touched.has(p.key) || !sameValue(values[p.key], shipped[p.key])).map((p) => p.key);
}

/** Whether the keys' `applies` ends in a server restart (a restart setting, or a reload setting on a mod with no reload command). */
export const sendNeedsRestart = (spec: ConfigSpec, applies: string) => applies === "restart" || (applies === "reload" && !spec.reload?.command);

export type ConfigReleaseView = { project: { id: string; namespace: string }; pluginName: string; spec: ConfigSpec; values: ConfigValues; revisionId: string; seq: number; message: string | null; changed: string[]; applies: string };

/**
 * What a send of one settings revision (default: the newest) carries: the full values of THAT revision as the studio
 * stored them, and the keys to write. Used by the enqueue side (to show what applies) and by the worker (which
 * re-reads everything from the store: the job payload only names the revision).
 */
export async function configReleaseFor(deps: ConfigServiceDeps, userId: string, rootBuildId: string, revisionId?: string | null): Promise<ConfigReleaseView> {
  const { src, project, schema, vrows } = await context(deps, userId, rootBuildId);
  if (!schema.spec || !project || !src.pluginName) throw new ConfigError(409, "no_settings", "This mod has no settings Cyrus can deliver.");
  if (!vrows.length) throw new ConfigError(409, "nothing_to_send", "There are no saved settings changes to send yet. Save a revision first.");
  const idx = revisionId ? vrows.findIndex((v) => v.row.revisionId === revisionId) : vrows.length - 1;
  if (idx < 0) throw new ConfigError(404, "not_found", "That settings revision is not in this mod.");
  const spec = schema.spec;
  const shipped = src.configYml ? readValues(spec, src.configYml).values : defaultsOf(spec);
  const row = vrows[idx];
  const values = { ...shipped, ...row.values } as ConfigValues;
  const changed = keysToSend(spec, shipped, values, vrows.slice(0, idx + 1).map((v) => v.patch));
  const rev = (await deps.store.revisions(project.id)).find((r) => r.id === row.row.revisionId);
  return { project: { id: project.id, namespace: project.namespace }, pluginName: src.pluginName, spec, values, revisionId: row.row.revisionId, seq: rev?.seq ?? 0, message: rev?.message ?? null, changed, applies: appliesFor(spec, changed).applies };
}

export type DeliverInput = { userId: string; rootBuildId: string; serverId: string; revisionId?: string | null; restartPolicy?: "now" | "next_restart"; acked?: string[]; idempotencyKey?: string | null };
/** Send the settings to one of the owner's servers: queues the host's delivery job (needs the host's delivery wiring). */
export async function deliverConfigValues(deps: ConfigServiceDeps, i: DeliverInput): Promise<ConfigDeliverResult> {
  if (!deps.deliver) throw new ConfigError(501, "delivery_not_connected", "Sending settings to a server is not connected here yet. Your settings are saved; they go out with the next install or update.");
  const r = await configReleaseFor(deps, i.userId, i.rootBuildId, i.revisionId ?? null);
  return deps.deliver({ userId: i.userId, serverId: i.serverId, projectId: r.project.id, rootBuildId: i.rootBuildId, revisionId: r.revisionId, pluginName: r.pluginName, spec: r.spec, values: r.values, changed: r.changed, applies: r.applies, restartPolicy: i.restartPolicy === "now" ? "now" : "next_restart", acked: i.acked ?? [], idempotencyKey: i.idempotencyKey ?? null });
}

