cat > lib/modbuilder/config-delivery.ts <<'EOF'
// Cyrus Config Studio "Send to server" (the HOST side; mirrors lib/modbuilder/delivery.ts). SERVER ONLY.
//   nxeonConfigDeliver(env)      the `deliver` dependency of the Config Studio API (app/api/cyrus/config/v1): checks the
//                                server like the install route does, that the mod is installed on it, the restart
//                                acknowledgement, then queues ONE GAME_MOD_SYNC job with the `cyrusDelivery` payload
//                                { op: "config", projectId, revisionId } through enqueueCyrusDelivery (per-server lock,
//                                idempotency key, one job per server, audit `cyrus.delivery.requested`). The worker
//                                (worker/cyrus-delivery.ts -> lib/cyrus/delivery/job.ts) re-reads the saved settings
//                                and runs deliverConfig; its outcome is on the job (poll /api/cyrus/delivery/v1/<jobId>).
//   installPlansWithConfig(...)  installPlansFor + `pendingConfig` per server: the install dialogs and the project page
//                                use it to say "Settings changed: send to server" instead of a dead end.
// Off unless CYRUS_DELIVERY=1 AND CYRUS_CONFIG_STUDIO=1 (the worker checks both again).
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { cyrusDb } from "../cyrus/db";
import { deliveryKey, ACK_TEXT } from "../cyrus/delivery/request";
import { ConfigError, sendNeedsRestart, type ConfigServiceDeps } from "../cyrus/config/service";
import { configStudioOn } from "../cyrus/config/route";
import { installPlansFor, type PendingConfig, type ServerPlan } from "../cyrus/lifecycle/server";
import { CYRUS_SOURCE } from "../cyrus/source";
import { checkServer, enqueueCyrusDelivery } from "./delivery";

const RANK = { none: 0, live: 1, reload: 2, restart: 3 } as const;
type Env = Record<string, string | undefined>;
const bothOn = (env: Env) => env.CYRUS_DELIVERY === "1" && configStudioOn(env);

/** The Config Studio's `deliver` dependency, or undefined while the delivery switch is off (the API then answers 501). */
export function nxeonConfigDeliver(env: Env = process.env): ConfigServiceDeps["deliver"] | undefined {
  if (env.CYRUS_DELIVERY !== "1") return undefined;
  return async (i) => {
    const { userId, serverId } = i;
    if (sendNeedsRestart(i.spec, i.applies) && i.restartPolicy === "now" && !i.acked.includes("restart")) {
      throw new ConfigError(409, "needs_ack", "Review and confirm the restart, then send.", { acks: [{ id: "restart", text: ACK_TEXT.restart }] });
    }
    const check = await checkServer({ userId, serverId });
    if (!check.ok) throw new ConfigError(check.status, check.code ?? "refused", check.error);
    // the mod must be installed on THAT server (the worker's preflight checks the plugin again on the server itself)
    const gm = await db.gameMod.findFirst({ where: { source: CYRUS_SOURCE, sourceId: i.rootBuildId }, select: { id: true } });
    const row = gm ? await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } }, select: { status: true } }) : null;
    if (!row || row.status !== "INSTALLED") throw new ConfigError(409, "not_installed", "This mod is not installed on that server yet. Install it first, then send its settings.");
    const k = deliveryKey({ userId, serverId, op: "config", subject: `${i.projectId}:${i.revisionId}`, restartPolicy: i.restartPolicy, clientKey: i.idempotencyKey });
    const q = await enqueueCyrusDelivery({
      userId, serverId, keyKind: k.kind, projectRootBuildId: i.rootBuildId,
      payload: { v: 1, op: "config", projectId: i.projectId, revisionId: i.revisionId, restartPolicy: i.restartPolicy, key: k.key, requestedBy: userId, ...(i.acked.length ? { acknowledge: i.acked } : {}) },
    });
    if (!q.ok) throw new ConfigError(q.status, q.code, q.error);
    return { ok: true, outcome: q.reused ? "already_queued" : "queued", jobId: q.jobId, reused: q.reused };
  };
}

const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

/** Per server (of `serverIds`): the saved settings revisions it has not been sent, or nothing when it is up to date / the studio is off. */
export async function pendingConfigByServer(build: Pick<ModBuild, "id" | "rootBuildId" | "userId">, userId: string, serverIds: string[], env: Env = process.env): Promise<Record<string, PendingConfig>> {
  if (!bothOn(env) || build.userId !== userId || !serverIds.length) return {};
  const root = build.rootBuildId ?? build.id;
  const project = await cyrusDb.cyrusProject.findFirst({ where: { rootBuildId: root, userId }, select: { id: true } }).catch(() => null);
  if (!project) return {};
  const rows = await cyrusDb.cyrusProjectAsset.findMany({ where: { projectId: project.id, kind: "config", assetKey: "values" }, orderBy: { createdAt: "asc" }, select: { revisionId: true, provenance: true } }).catch(() => []);
  if (!rows.length) return {};
  const revs = await cyrusDb.cyrusRevision.findMany({ where: { id: { in: rows.map((r) => r.revisionId) } }, select: { id: true, seq: true, message: true } });
  const revOf = new Map(revs.map((r) => [r.id, r]));
  // a send that finished OK is a DONE job (the job body throws, so FAILED, whenever the delivery did not succeed)
  const jobs = await db.job.findMany({ where: { type: "GAME_MOD_SYNC", status: "DONE", serverId: { in: serverIds }, payload: { path: ["cyrusDelivery", "op"], equals: "config" } }, orderBy: { createdAt: "desc" }, take: 300, select: { serverId: true, payload: true } });
  const sent = new Map<string, Set<string>>();
  for (const j of jobs) {
    const d = obj(obj(j.payload).cyrusDelivery);
    if (d.projectId !== project.id || typeof d.revisionId !== "string" || !j.serverId) continue;
    (sent.get(j.serverId) ?? sent.set(j.serverId, new Set()).get(j.serverId)!).add(d.revisionId);
  }
  const out: Record<string, PendingConfig> = {};
  for (const sid of serverIds) {
    const done = sent.get(sid) ?? new Set<string>();
    let last = -1;
    rows.forEach((r, i) => { if (done.has(r.revisionId)) last = i; });
    const pending = rows.slice(last + 1);
    if (!pending.length) continue;
    const newest = pending[pending.length - 1];
    let applies: PendingConfig["applies"] = "none";
    for (const r of pending) { const a = obj(r.provenance).applies; if (a === "live" || a === "reload" || a === "restart") if (RANK[a] > RANK[applies]) applies = a; }
    out[sid] = { root, revisionId: newest.revisionId, seq: revOf.get(newest.revisionId)?.seq ?? 0, message: revOf.get(newest.revisionId)?.message ?? null, applies, revisions: pending.length };
  }
  return out;
}

/** installPlansFor + `pendingConfig` on every server where the mod is installed (any version) and settings were not sent yet. */
export async function installPlansWithConfig(build: ModBuild, actorId: string, env: Env = process.env): Promise<{ game: string; plans: ServerPlan[] }> {
  const r = await installPlansFor(build, actorId);
  if (!bothOn(env)) return r;
  const installed = r.plans.filter((p) => p.plan.op !== "install").map((p) => p.server.id);
  const pend = await pendingConfigByServer(build, actorId, installed, env).catch(() => ({}) as Record<string, PendingConfig>);
  return { ...r, plans: r.plans.map((p) => (pend[p.server.id] ? { ...p, pendingConfig: pend[p.server.id] } : p)) };
}
EOF

