"use client";

// Config Studio "Send to server", client side, shared by the studio drawer, the install dialogs and the project page.
// POST /api/cyrus/config/v1 { action: "deliver" } queues the delivery job; then GET /api/cyrus/delivery/v1/<jobId> is
// polled until it is no longer pending. The status is the worker's own read model (lib/cyrus/delivery/request.ts
// deliveryStatus): it says rolled back / failed exactly as it happened, it is never softened here.
import { useCallback, useEffect, useRef, useState } from "react";

export type SendStatus = { jobId: string; state: string; pending: boolean; ok: boolean | null; headline: string; needsAttention: boolean; error: string | null; notes: string[] };

/** The words for what applying will do (one place, so the dialogs and the studio agree). */
export const SEND_APPLY_TEXT: Record<string, string> = {
  live: "The mod picks these settings up on its own.",
  reload: "The mod reloads its settings, no restart.",
  restart: "These settings load when the server restarts.",
  none: "",
};
export const SEND_PROMISE = "We merge only the settings you changed into the server's own config file (its comments and your other edits stay), check it, and put the old file back if anything fails.";

export function useSendSettings(root: string, serverId: string | null, applies: string | null) {
  const [restartNow, setRestartNow] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [status, setStatus] = useState<SendStatus | null>(null);
  const alive = useRef(true);
  const inflight = useRef(false);
  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);
  useEffect(() => { setStatus(null); setErr(null); setRestartNow(false); }, [serverId, root]);

  const send = useCallback(async () => {
    if (!serverId || inflight.current) return; // a double click is one send (the server also derives one idempotency key)
    inflight.current = true;
    setBusy(true); setErr(null); setStatus(null);
    try {
      const wantRestart = restartNow && applies === "restart";
      const r = await fetch("/api/cyrus/config/v1", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ root, action: "deliver", serverId, restartPolicy: wantRestart ? "now" : "next_restart", acked: wantRestart ? ["restart"] : [] }) });
      const j = (await r.json().catch(() => ({}))) as { jobId?: string; error?: string };
      if (!r.ok || !j.jobId) { setErr(j.error || "We couldn't send the settings. Nothing on your server was changed."); return; }
      const jobId = j.jobId;
      setStatus({ jobId, state: "queued", pending: true, ok: null, headline: "Waiting for the server to be free.", needsAttention: false, error: null, notes: [] });
      const until = Date.now() + 10 * 60_000;
      while (alive.current && Date.now() < until) {
        await new Promise((res) => setTimeout(res, 2500));
        const s = await fetch(`/api/cyrus/delivery/v1/${encodeURIComponent(jobId)}`, { cache: "no-store" }).then((x) => (x.ok ? x.json() : null)).catch(() => null) as { status?: SendStatus } | null;
        if (!alive.current) return;
        if (!s?.status) continue;
        setStatus({ ...s.status, jobId });
        if (!s.status.pending) return;
      }
    } catch { setErr("We couldn't reach Nxeon. Nothing on your server was changed; try again."); }
    finally { inflight.current = false; if (alive.current) setBusy(false); }
  }, [root, serverId, restartNow, applies]);

  return { restartNow, setRestartNow, busy, err, status, send, done: !!status && !status.pending };
}
EOF

