cd /tank/dev-worktrees/cyrus-configdeliver && cat > components/cyrus/config/SendSettingsPanel.tsx <<'EOF'
"use client";

// "Settings changed: send to server": the panel the install dialogs and the project page show when a server runs this
// mod but has not been sent the settings saved in the Config Studio. It replaces the old dead end ("already has this
// version", Install disabled). Same behaviour in three skins (the Cyrus kit, the portal tokens, the Cyrus app).
import type { PendingConfig } from "@/lib/cyrus/lifecycle/server";
import { SEND_APPLY_TEXT, SEND_PROMISE, useSendSettings } from "./useSendSettings";

type Skin = "cy" | "tw" | "cx";
const K: Record<Skin, { box: string; head: string; p: string; btn: string; check: string; err: string; ok: string; bad: string }> = {
  cy: { box: "cy-lc-list warn", head: "font-semibold", p: "cy-sub", btn: "cy-btn primary", check: "cy-checkrow", err: "cy-err", ok: "cy-sub", bad: "cy-err" },
  tw: { box: "flex flex-col gap-2 rounded-[12px] border border-violet/45 bg-violet/[0.07] p-3", head: "text-[13px] font-bold text-tx", p: "text-[12px] leading-relaxed text-tx-dim", btn: "btn-primary text-[12.5px] disabled:opacity-50", check: "flex cursor-pointer gap-2.5 text-[12.5px] text-tx", err: "text-[12.5px] text-rose", ok: "text-[12.5px] font-bold text-mint", bad: "text-[12.5px] font-bold text-rose" },
  cx: { box: "cx-note", head: "cx-t", p: "cx-faint", btn: "cx-btn cx-btn-pri", check: "cx-check", err: "cx-error", ok: "cx-okmsg", bad: "cx-error" },
};

export function SendSettingsPanel({ serverId, serverName, pending, blockers = [], skin = "cy" }: { serverId: string; serverName: string; pending: PendingConfig; blockers?: string[]; skin?: Skin }) {
  const k = K[skin];
  const s = useSendSettings(pending.root, serverId, pending.applies);
  const n = pending.revisions;
  const blocked = blockers.length > 0;
  return (
    <div className={k.box} style={skin === "cx" ? { display: "grid", gap: 8 } : undefined} data-testid="cyrus-send-settings">
      <b className={k.head}>Settings changed: send to server</b>
      <p className={k.p}>
        {n === 1 ? "1 saved settings change" : `${n} saved settings changes`}{pending.message ? ` (latest: ${pending.message})` : ""} {n === 1 ? "has" : "have"} not been sent to {serverName}. The mod itself is already up to date there, so there is nothing to reinstall.
      </p>
      {SEND_APPLY_TEXT[pending.applies] ? <p className={k.p}>{SEND_APPLY_TEXT[pending.applies]}</p> : null}
      <p className={k.p}>{SEND_PROMISE}</p>
      {blockers.map((b) => <p key={b} className={k.err}>{b}</p>)}
      {pending.applies === "restart" && !s.done ? (
        <label className={k.check}>
          <input type="checkbox" checked={s.restartNow} onChange={(e) => s.setRestartNow(e.target.checked)} />
          <span><b>Restart the server now</b> so the settings load (players are disconnected for about a minute). Leave it off to send the file now and restart yourself later.</span>
        </label>
      ) : null}
      {s.err ? <p role="alert" className={k.err}>{s.err}</p> : null}
      {s.status ? <p role="status" className={s.status.pending ? k.p : s.status.ok ? k.ok : k.bad}>{s.status.headline}{!s.status.pending && !s.status.ok && s.status.error ? ` ${s.status.error}` : ""}</p> : null}
      {s.status && !s.status.pending ? s.status.notes.filter((x) => /^warning:/.test(x)).map((x) => <p key={x} className={k.p}>{x.replace(/^warning:\s*/, "Heads up: ")}</p>) : null}
      {!s.done ? <div><button type="button" className={k.btn} disabled={s.busy || blocked} onClick={() => void s.send()}>{s.busy ? "Sending…" : `Send settings to ${serverName}`}</button></div> : null}
    </div>
  );
}
EOF

