"use client";

// Config Studio: the "Send to server" drawer. Lists the servers that run this mod (the install plans, one per server of
// the owner) and, for the chosen one, the same SendSettingsPanel the install dialogs show.
import { useEffect, useState } from "react";
import { getCyrusInstallPlans } from "@/lib/actions-cyrus-lifecycle";
import type { ServerPlan } from "@/lib/cyrus/lifecycle/server";
import { SI } from "@/components/cyrus/studios/icons";
import { SendSettingsPanel } from "./SendSettingsPanel";

export function SendDrawer({ buildId, onClose }: { buildId: string; onClose: () => void }) {
  const [plans, setPlans] = useState<ServerPlan[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [sel, setSel] = useState<string | null>(null);
  useEffect(() => {
    let live = true;
    getCyrusInstallPlans(buildId).then((r) => {
      if (!live) return;
      if (r.error || !r.plans) return setErr(r.error ?? "Couldn't check your servers.");
      const on = r.plans.filter((p) => p.plan.op !== "install");
      setPlans(on);
      setSel((on.find((p) => p.pendingConfig) ?? on[0])?.server.id ?? null);
    }).catch(() => live && setErr("Couldn't check your servers."));
    return () => { live = false; };
  }, [buildId]);
  const chosen = plans?.find((p) => p.server.id === sel) ?? null;
  return (
    <div className="cfg-drawer cys-glass cys-hairline" role="dialog" aria-label="Send to server">
      <div className="dh"><SI n="server" /><h3>Send settings to a server</h3><span className="sp" /><button className="cys-ib" onClick={onClose} aria-label="Close"><SI n="close" /></button></div>
      {!plans && !err && <p className="cys-hint" style={{ padding: 16 }} role="status">Checking your servers…</p>}
      {err && <div className="cfg-warn bad" style={{ margin: 16 }}><SI n="warn" />{err}</div>}
      {plans && plans.length === 0 && <p className="cys-hint" style={{ padding: 16 }}>This mod is not installed on a server of yours yet. Install it from the project page, then send its settings.</p>}
      {plans && plans.length > 0 && (
        <>
          <div className="srvs" role="radiogroup" aria-label="Server">
            {plans.map((p) => (
              <label key={p.server.id} className={`srv ${sel === p.server.id ? "on" : ""}`}>
                <input type="radio" name="cfg-send-srv" className="sr-only" checked={sel === p.server.id} onChange={() => setSel(p.server.id)} />
                <b>{p.server.name}</b><span className="cys-hint">{p.server.status === "RUNNING" ? "online" : "stopped"}</span><span className="sp" />
                <span className={`cys-tag ${p.pendingConfig ? "acc" : "ok"}`}>{p.pendingConfig ? "Settings changed" : "Up to date"}</span>
              </label>
            ))}
          </div>
          {chosen && (chosen.pendingConfig
            ? <SendSettingsPanel skin="cys" serverId={chosen.server.id} serverName={chosen.server.name} pending={chosen.pendingConfig} blockers={chosen.plan.blockers} />
            : <p className="cys-hint" style={{ padding: 16 }}>{chosen.server.name} already has your latest saved settings.</p>)}
        </>
      )}
    </div>
  );
}
EOF
