import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * Cyrus R5 DB checks against a THROWAWAY Postgres (node-2 agent DB only): managed-plugin refs snapshot/restore (the
 * delivery rollback), a delivery with the REAL managed-plugin service whose health check fails (refs restored exactly),
 * the atomic jsonb merge of ModBuild.cyrus keys (engineRelease / testFlight never lose a concurrent write), the engine
 * release stored on a CyrusRevision, and the admin read model's JSON-path query over real Job / ModBuild rows.
 * Opt-in, fail-closed: CYRUS_DELIVERY_DB_TEST=1 and DATABASE_URL = 127.0.0.1:5433/wt_*. Schema: `devhost db push`.
 *   devhost run --lock -- env CYRUS_DELIVERY_DB_TEST=1 npx tsx --test test/cyrus-delivery-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_DELIVERY_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_DELIVERY_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
const uniq = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const KEY = "nxeon-pack-loader";

before(async () => { if (safe) db = (await import("../lib/db.ts")).db; });
after(async () => {
  if (!safe) return;
  await db.cyrusServerManagedPlugin.deleteMany({ where: { serverId: { startsWith: `cyd-${uniq}` } } });
  await db.modBuild.deleteMany({ where: { id: { startsWith: `cyd${uniq}` } } });
  await db.job.deleteMany({ where: { step: `cyd-${uniq}` } });
  await db.$disconnect();
});

describe("Cyrus R5 delivery (throwaway DB)", { skip }, () => {
  it("managed refs: snapshot, change, restore = the exact previous rows (new rows removed)", async () => {
    const S = await import("../lib/cyrus/managed/service.ts");
    const I = await import("../lib/cyrus/managed/installer.ts");
    const C = await import("../lib/cyrus/managed/catalog.ts");
    const deps = { db, installer: I.memoryInstaller(), catalog: C.loadCatalog() };
    const sid = `cyd-${uniq}-a`;
    assert.ok((await S.ensureManagedPlugin(deps, { serverId: sid, key: KEY, mcVersion: "1.21.11", dependent: "project:p1" })).ok);
    const snap = await S.snapshotServerManaged(db, sid);
    assert.ok((await S.ensureManagedPlugin(deps, { serverId: sid, key: KEY, mcVersion: "1.21.11", dependent: "project:p2" })).ok);
    await db.cyrusServerManagedPlugin.create({ data: { serverId: sid, key: "bettermodel", family: "26", status: "installed", dependents: ["project:p2"], refCount: 1 } });
    await S.restoreServerManaged(db, snap);
    const after = await S.snapshotServerManaged(db, sid);
    assert.deepEqual(after, snap);
  });

  it("a delivery whose health check fails restores the database refs exactly (real service, fake server)", async () => {
    const S = await import("../lib/cyrus/managed/service.ts");
    const I = await import("../lib/cyrus/managed/installer.ts");
    const C = await import("../lib/cyrus/managed/catalog.ts");
    const { deliverMod } = await import("../lib/cyrus/delivery/orchestrator.ts");
    const { FakeServer, seedServer, h } = await import("./_cyrus-delivery-fakehost.ts");
    const { jarOf, goodMod, rpZip } = await import("./_cyrus-modfixture.ts");
    const { createHash } = await import("node:crypto");
    const sid = `cyd-${uniq}-b`;
    const s = new FakeServer(); seedServer(s);
    try {
      const catalog = C.loadCatalog();
      const deps = { db, installer: I.memoryInstaller(), catalog };
      const base = s.host({ failStep: "health" });
      const host = {
        ...base,
        managed: {
          async ensure(a: { serverId: string; key: string; mcVersion: string; dependent: string }) { const r = await S.ensureManagedPlugin(deps, a); return r.ok ? { ok: true as const, action: r.action, pluginName: "NxeonPackLoader" } : { ok: false as const, error: r.error }; },
          async release(a: { serverId: string; key: string; dependent: string }) { const r = await S.releaseManagedPlugin(deps, a); return r.ok ? { ok: true as const, action: r.action } : { ok: false as const, error: r.error }; },
          snapshot: (id: string) => S.snapshotServerManaged(db, id),
          async restore(_id: string, snap: unknown) { await S.restoreServerManaged(db, snap as never); return { ok: true as const }; },
        },
      };
      const before = await S.snapshotServerManaged(db, sid);
      const m = goodMod("nx_dbdeliv1", "alpha"); const jar = jarOf(m); const rp = rpZip(m);
      const r = await deliverMod(sid, { projectId: "cp_db1", revisionId: "r1", namespace: "nx_dbdeliv1", mcVersion: "1.21.11", label: "A", plugin: { pluginName: m.name, jarName: "A.jar", sha256: h(jar), bytes: jar }, pack: { sha1: createHash("sha1").update(rp).digest("hex"), zip: rp, prompt: "p", required: false }, datapacks: [], creatures: [] }, host);
      assert.equal(r.outcome, "rolled_back", JSON.stringify(r.steps));
      assert.equal(r.rollback?.refs, "restored");
      assert.deepEqual(await S.snapshotServerManaged(db, sid), before);
    } finally { s.cleanup(); }
  });

  it("ModBuild.cyrus keys merge atomically: concurrent engineRelease + testFlight + an existing title all survive", async () => {
    const { mergeCyrusKey } = await import("../lib/modbuilder/store.ts");
    const id = `cyd${uniq}m1`;
    await db.modBuild.create({ data: { id, userId: `u-${uniq}`, prompt: "p", mcVersion: "1.21.11", status: "succeeded", cyrus: { title: "Keep me" } } });
    await Promise.all([mergeCyrusKey(id, "engineRelease", { schema: 1, id: "x" }), mergeCyrusKey(id, "testFlight", { schema: 1, state: "done" })]);
    const row = await db.modBuild.findUnique({ where: { id } });
    const c = row!.cyrus as Record<string, unknown>;
    assert.equal(c.title, "Keep me"); assert.deepEqual(c.engineRelease, { schema: 1, id: "x" }); assert.deepEqual(c.testFlight, { schema: 1, state: "done" });
    const id2 = `cyd${uniq}m2`;
    await db.modBuild.create({ data: { id: id2, userId: `u-${uniq}`, prompt: "p", mcVersion: "1.21.11" } });
    await mergeCyrusKey(id2, "testFlight", { schema: 1 });
    assert.deepEqual((await db.modBuild.findUnique({ where: { id: id2 } }))!.cyrus, { testFlight: { schema: 1 } }, "null meta becomes an object with the key");
  });

  it("admin read model: deliveries by JSON-path, flights + engines + pass rates from stored rows", async () => {
