//   - the mod must be INSTALLED on that server (a row that is mid-install/update/removal answers busy);
//   - double clicks: the derived idempotency key returns the same job while it is queued or running.
import { ConfigError, sendNeedsRestart, type ConfigServiceDeps } from "../config/service";
import { ACK_TEXT, deliveryKey } from "./request";
import type { EnqueueInput, EnqueueResult, HostCheck } from "./api";
import type { Env } from "./types";

export type ConfigSendDeps = {
  env: Env;
  checkServer(a: { userId: string; serverId: string }): Promise<HostCheck>;
  /** The install row of this mod on this server (Nxeon: ServerMod.status), null = none. */
  installState(rootBuildId: string, serverId: string): Promise<string | null>;
  enqueue(a: EnqueueInput): Promise<EnqueueResult>;
};

export function configDeliverWith(d: ConfigSendDeps): ConfigServiceDeps["deliver"] | undefined {
  if (d.env.CYRUS_DELIVERY !== "1") return undefined;
  return async (i) => {
    const { userId, serverId } = i;
    if (sendNeedsRestart(i.spec, i.applies) && i.restartPolicy === "now" && !i.acked.includes("restart")) {
      throw new ConfigError(409, "needs_ack", "Review and confirm the restart, then send.", { acks: [{ id: "restart", text: ACK_TEXT.restart }] });
    }
    const check = await d.checkServer({ userId, serverId });
    if (!check.ok) throw new ConfigError(check.status, check.code ?? "refused", check.error);
    const state = await d.installState(i.rootBuildId, serverId);
    if (!state || state === "REMOVED") throw new ConfigError(409, "not_installed", "This mod is not installed on that server yet. Install it first, then send its settings.");
    if (state !== "INSTALLED") throw new ConfigError(409, "busy", `This mod is ${state.toLowerCase()} on that server right now. Send the settings when it shows as installed.`);
    const k = deliveryKey({ userId, serverId, op: "config", subject: `${i.projectId}:${i.revisionId}`, restartPolicy: i.restartPolicy, clientKey: i.idempotencyKey });
    const q = await d.enqueue({
      userId, serverId, keyKind: k.kind, projectRootBuildId: i.rootBuildId,
      payload: { v: 1, op: "config", projectId: i.projectId, revisionId: i.revisionId, restartPolicy: i.restartPolicy, key: k.key, requestedBy: userId, ...(i.acked.length ? { acknowledge: i.acked } : {}) },
    });
    if (!q.ok) throw new ConfigError(q.status, q.code, q.error);
    return { ok: true, outcome: q.reused ? "already_queued" : "queued", jobId: q.jobId, reused: q.reused };
  };
}
