// Cyrus Config Studio "Send to server" (the HOST side; mirrors lib/modbuilder/delivery.ts). SERVER ONLY.
//   nxeonConfigDeliver(env)      the `deliver` dependency of the Config Studio API (app/api/cyrus/config/v1): checks the
//                                server like the install route does, that the mod is installed on it, the restart
//                                acknowledgement, then queues ONE GAME_MOD_SYNC job with the `cyrusDelivery` payload
//                                { op: "config", projectId, revisionId } through enqueueCyrusDelivery (per-server lock,
//                                idempotency key, one job per server, audit `cyrus.delivery.requested`). The worker
//                                (worker/cyrus-delivery.ts -> lib/cyrus/delivery/job.ts) re-reads the saved settings
//                                and runs deliverConfig; its outcome is on the job (poll /api/cyrus/delivery/v1/<jobId>).
//   installPlansWithConfig(...)  installPlansFor + `pendingConfig` per server: the install dialogs and the project page
//                                use it to say "Settings changed: send to server" instead of a dead end.
// Off unless CYRUS_DELIVERY=1 AND CYRUS_CONFIG_STUDIO=1 (the worker checks both again).
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { cyrusDb } from "../cyrus/db";
import { configDeliverWith } from "../cyrus/delivery/config-send";
import type { ConfigServiceDeps } from "../cyrus/config/service";
import { configStudioOn } from "../cyrus/config/route";
import { installPlansFor, type PendingConfig, type ServerPlan } from "../cyrus/lifecycle/server";
import { CYRUS_SOURCE } from "../cyrus/source";
import { checkServer, enqueueCyrusDelivery } from "./delivery";

const RANK = { none: 0, live: 1, reload: 2, restart: 3 } as const;
type Env = Record<string, string | undefined>;
const bothOn = (env: Env) => env.CYRUS_DELIVERY === "1" && configStudioOn(env);

/** The Config Studio's `deliver` dependency, or undefined while the delivery switch is off (the API then answers 501). Logic: lib/cyrus/delivery/config-send.ts. */
export function nxeonConfigDeliver(env: Env = process.env): ConfigServiceDeps["deliver"] | undefined {
  return configDeliverWith({
    env, checkServer, enqueue: enqueueCyrusDelivery,
    async installState(rootBuildId, serverId) {
      const gm = await db.gameMod.findFirst({ where: { source: CYRUS_SOURCE, sourceId: rootBuildId }, select: { id: true } });
      return gm ? (await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } }, select: { status: true } }))?.status ?? null : null;
    },
  });
}

const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

/** Per server (of `serverIds`): the saved settings revisions it has not been sent, or nothing when it is up to date / the studio is off. */
export async function pendingConfigByServer(build: Pick<ModBuild, "id" | "rootBuildId" | "userId">, userId: string, serverIds: string[], env: Env = process.env): Promise<Record<string, PendingConfig>> {

