// Config Studio: which saved settings revisions a server has NOT been sent (PURE; the DB reads are in
// lib/modbuilder/config-delivery.ts). A send that finished OK is a DONE delivery job (the job body fails the job whenever
// the delivery did not succeed), so "sent" = a revision id named by a DONE `config` job on that server. Every revision
// AFTER the newest sent one is pending (an Undo is a new revision, so it is pending too).
import type { PendingConfig } from "../lifecycle/server";

const RANK = { none: 0, live: 1, reload: 2, restart: 3 } as const;
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

export type PendingRow = { revisionId: string; provenance: unknown };
export type PendingRev = { id: string; seq: number; message: string | null };

export function pendingConfigFrom(a: { root: string; rows: readonly PendingRow[]; revs: readonly PendingRev[]; sentByServer: ReadonlyMap<string, ReadonlySet<string>>; serverIds: readonly string[] }): Record<string, PendingConfig> {
  const out: Record<string, PendingConfig> = {};
  if (!a.rows.length) return out;
  const revOf = new Map(a.revs.map((r) => [r.id, r]));
  for (const sid of a.serverIds) {
    const done = a.sentByServer.get(sid);
    let last = -1;
    a.rows.forEach((r, i) => { if (done?.has(r.revisionId)) last = i; });
    const pending = a.rows.slice(last + 1);
    if (!pending.length) continue;
    const newest = pending[pending.length - 1];
    let applies: PendingConfig["applies"] = "none";
    for (const r of pending) { const x = obj(r.provenance).applies; if ((x === "live" || x === "reload" || x === "restart") && RANK[x] > RANK[applies]) applies = x; }
    const rev = revOf.get(newest.revisionId);
    out[sid] = { root: a.root, revisionId: newest.revisionId, seq: rev?.seq ?? 0, message: rev?.message ?? null, applies, revisions: pending.length };
  }
  return out;
}
