  { key: "mobs.frost.biomes", group: "s", type: "list", label: "Biomes", default: [], item: { type: "text" }, applies: "restart" },
] }); assert.ok(r.ok); return (r as { spec: ConfigSpec }).spec; };
const H = "mobs.frost.health", SP = "mobs.frost.speed", BI = "mobs.frost.biomes";

function memStore(userId = "u1") {
  const revs: RevRow[] = [];
  const rows: AssetRow[] = [];
  let t = Date.parse("2026-10-10T10:00:00Z");
  const project = { id: "cp00000000000000000001", userId, namespace: "nx_frost001", rootBuildId: "b1", headRevisionId: null as string | null, title: null };
  const store: ConfigServiceDeps["store"] = {
    projectForRoot: async (r) => (r === "b1" ? project : null),
    assets: async () => rows,
    revisions: async () => revs,
    addRevision: async (_p, i) => {
      const head = revs[revs.length - 1]?.id ?? null;
      if (i.expectedHeadId !== undefined && i.expectedHeadId !== head) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const r = { id: `rev${revs.length + 1}`, seq: revs.length + 1, kind: i.kind, status: i.status ?? "pending", message: i.message ?? null, createdAt: new Date(t += 1000), manifest: i.manifest as RevRow["manifest"], modBuildId: null };
      revs.push(r); project.headRevisionId = r.id; return { id: r.id, seq: r.seq };
    },
    recordAsset: async (projectId, a) => { const row = { id: `a${rows.length + 1}`, projectId, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t += 1000) }; rows.push(row); return { id: row.id }; },
  };
  return { store, revs, rows, project };
}
const source = (): ConfigSource => ({ buildId: "b1", pluginName: "FrostMobs", mcVersion: "1.21.11", configYml: YML, pluginYml: PLUGIN, declared: { source: "declared", spec: SPEC() } });

type Env = Record<string, string | undefined>;
const ON: Env = { CYRUS_DELIVERY: "1", CYRUS_CONFIG_STUDIO: "1" };

/** One account (u1), one server (s1) with FrostMobs installed, a studio store, the in-memory queue and the worker. */
function world(o: { reply?: string; web?: Env; workerEnv?: Env; hostEnv?: Env; eligible?: boolean; modState?: string | null; plugin?: boolean } = {}) {
  const s = new FakeServer();
