  const open = host.open.bind(host);
  host.open = async (id) => { const sess = await open(id); return { ...sess, console: async (cmd: string) => { s.consoleLog.push(cmd); return { ok: true as const, reply: cmd === "frost reload" ? (o.reply ?? "FrostMobs config reloaded") : "ok" }; } }; };

  const m = memStore();
  const portal = new MemPortal();
  portal.servers.set("s1", { id: "s1", userId: "u1", name: "Alpha", eligible: o.eligible ?? true });
  portal.servers.set("s2", { id: "s2", userId: "u2", name: "Theirs", eligible: true });
  portal.projects.set(m.project.id, { id: m.project.id, namespace: "nx_frost001", userId: "u1", rootBuildId: "b1" });
  const base: ConfigServiceDeps = { store: m.store, source: async (u, r) => (u === "u1" && r === "b1" ? source() : null) };
  let seq = 0;
