    const srv = portal.servers.get(a.serverId);
    if (!srv || srv.userId !== a.userId) return { ok: false, status: 404, error: "Server not found.", code: "not_found" };
    const same = [...portal.jobs].reverse().find((j) => j.serverId === a.serverId && (j.payload as { cyrusDelivery?: { key?: string } }).cyrusDelivery?.key === a.payload.key);
    if (same && reuseExisting(a.keyKind, same.status)) return { ok: true, jobId: same.id, reused: true };
    if (portal.jobs.some((j) => j.serverId === a.serverId && (j.status === "QUEUED" || j.status === "RUNNING"))) return { ok: false, status: 409, error: "Another operation is already running on this server. Try again when it finishes.", code: "busy" };
    const at = new Date(Date.parse("2026-10-12T12:00:00Z") + ++seq * 1000);
    portal.jobs.push({ id: `job_${seq}`, serverId: a.serverId, status: "QUEUED", error: null, payload: { cyrusDelivery: a.payload }, createdAt: at, updatedAt: at, attempts: 0 });
    portal.audit.push({ userId: a.userId, action: "cyrus.delivery.requested", detail: `${a.serverId} job=job_${seq} ${a.payload.op}` });
