    if (!srv || srv.userId !== a.userId) return { ok: false, status: 404, error: "Server not found.", code: "not_found" };
    return srv.eligible ? { ok: true, serverName: srv.name } : { ok: false, status: 409, error: "Start the server first: mods are changed on the running server.", code: "not_eligible" };
  };
