  const post = (b: unknown, user = "u1") => handleConfig(new Request("http://x/api/cyrus/config/v1", { method: "POST", body: JSON.stringify(b) }), api(user));
  const get = (user = "u1") => handleConfig(new Request("http://x/api/cyrus/config/v1?root=b1"), api(user));
