// Config Studio "Send to server" end to end, in memory: the Config API (handleConfig, action "deliver") -> the host's
// enqueue (configDeliverWith: flags, ownership, install state, acks, idempotency) -> ONE delivery job { op: "config" } ->
// the REAL job body (runDeliveryJob) -> the REAL orchestrator (deliverConfig) against the fake server -> the status read
// model the Install dialogs / the Studio poll. Plus the pure rules (payload, keys to send, pending revisions, the
// warn-don't-block value check). The real-server run is test/cyrus-config-delivery-real.ts (node-2).
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { keysToSend, sendNeedsRestart } from "../lib/cyrus/config/service";
import { validateConfigSpec, type ConfigSpec } from "../lib/cyrus/config/spec";
import { pendingConfigFrom } from "../lib/cyrus/config/pending";
import { checkConfigValuesSoft } from "../lib/cyrus/delivery/config-check";
import { deliverConfig } from "../lib/cyrus/delivery/orchestrator";
import { deliveryKey, parseDeliveryPayload, readDeliveryPayload } from "../lib/cyrus/delivery/request";
import { FakeServer, seedServer, pluginJar } from "./_cyrus-delivery-fakehost";
import { configWorld, type Env } from "./_cyrus-config-world";

const YML = "# FrostMobs\nmobs:\n  frost:\n    # Health in half-hearts (1-1024)\n    health: 40\n    speed: 0.25  # walk speed\n";
const PLUGIN = "name: FrostMobs\ncommands:\n  frost:\n    usage: /frost reload\n";
const SPEC = () => { const r = validateConfigSpec({ schemaVersion: 1, reload: { command: "/frost reload" }, groups: [{ id: "s", label: "S" }], params: [
  { key: "mobs.frost.health", group: "s", type: "int", label: "Health", default: 40, min: 1, max: 1024, applies: "reload" },
  { key: "mobs.frost.speed", group: "s", type: "number", label: "Speed", default: 0.25, min: 0, max: 1, applies: "reload" },
  { key: "mobs.frost.biomes", group: "s", type: "list", label: "Biomes", default: [], item: { type: "text" }, applies: "restart" },
] }); assert.ok(r.ok); return (r as { spec: ConfigSpec }).spec; };
const H = "mobs.frost.health", SP = "mobs.frost.speed", BI = "mobs.frost.biomes";

/** The fake server (a temp dir) with FrostMobs installed, wired into the shared Config Studio world. */
function world(o: { reply?: string; web?: Env; workerEnv?: Env; hostEnv?: Env; eligible?: boolean; modState?: string | null; plugin?: boolean } = {}) {
  const s = new FakeServer();
  seedServer(s);
  const w = (rel: string, d: Buffer | string) => { mkdirSync(path.dirname(path.join(s.dir, rel)), { recursive: true }); writeFileSync(path.join(s.dir, rel), d); };
  if (o.plugin !== false) w("opt/mc/plugins/FrostMobs-1.0.0.jar", pluginJar("FrostMobs"));
  w("opt/mc/plugins/FrostMobs/config.yml", YML);
  s.booted = s.boot();
  const host = s.host({ env: { CYRUS_CONFIG_STUDIO: "1", ...(o.hostEnv ?? {}) } });
  const open = host.open.bind(host);
  host.open = async (id) => { const sess = await open(id); return { ...sess, console: async (cmd: string) => { s.consoleLog.push(cmd); return { ok: true as const, reply: cmd === "frost reload" ? (o.reply ?? "FrostMobs config reloaded") : "ok" }; } }; };
  const cw = configWorld({ host, spec: SPEC(), yml: YML, pluginName: "FrostMobs", pluginYml: PLUGIN, web: o.web, workerEnv: o.workerEnv, eligible: o.eligible, modState: o.modState });
  return { s, host, ...cw, file: () => s.read("opt/mc/plugins/FrostMobs/config.yml")!.toString(), tree: () => s.tree({ excludeJournal: true }) };
}

describe("payload, keys, pending revisions, value check (pure)", () => {
  it("op config needs a project and a revision; the discriminator reads it back", () => {
    assert.equal(parseDeliveryPayload({ v: 1, op: "config", projectId: "cp1" }), null);
    assert.equal(parseDeliveryPayload({ v: 1, op: "config", revisionId: "r1" }), null);
    const p = parseDeliveryPayload({ v: 1, op: "config", projectId: "cp1", revisionId: "r1", restartPolicy: "next_restart", acknowledge: ["restart"] })!;
    assert.deepEqual(p, { v: 1, op: "config", projectId: "cp1", revisionId: "r1", restartPolicy: "next_restart", acknowledge: ["restart"] });
    assert.deepEqual(readDeliveryPayload({ cyrusDelivery: p }), p);
    const k1 = deliveryKey({ userId: "u", serverId: "s", op: "config", subject: "cp1:r1", restartPolicy: "next_restart" });
    assert.notEqual(k1.key, deliveryKey({ userId: "u", serverId: "s", op: "config", subject: "cp1:r2", restartPolicy: "next_restart" }).key, "another revision is another send");
  });
  it("keysToSend: what differs from the build PLUS every key a revision touched (a key set back reaches the server)", () => {
    const spec = SPEC();
    const shipped = { [H]: 40, [SP]: 0.25, [BI]: [] };
    assert.deepEqual(keysToSend(spec, shipped, { ...shipped, [H]: 80 }, [[{ key: H, from: 40, to: 80 }]]), [H]);
    assert.deepEqual(keysToSend(spec, shipped, shipped, [[{ key: H, from: 40, to: 80 }], [{ key: H, from: 80, to: 40 }]]), [H], "reverted to shipped: still written");
    assert.deepEqual(keysToSend(spec, shipped, { ...shipped, [SP]: 0.4 }, [[{ key: H, from: 40, to: 80 }], [{ key: SP, from: 0.25, to: 0.4 }]]), [H, SP]);
    assert.equal(sendNeedsRestart(spec, "reload"), false);

/** Stat -> viewport links (./visual.ts): clip playback rate, model scale, fire cadence, colour. */
export const VISUAL_CHANNELS = ["clipRate", "attackRate", "scale", "fireRate", "tint"] as const;
export type VisualChannel = (typeof VISUAL_CHANNELS)[number];

export const DURATION_UNITS = ["ticks", "s", "ms"] as const;
export type DurationUnit = (typeof DURATION_UNITS)[number];
export const ASSET_REF_KINDS = ["texture", "model", "sound", "item"] as const;

export const CONFIG_LIMITS = { params: 400, groups: 32, presets: 12, options: 64, listItems: 256, tableRows: 256, columns: 12, textChars: 1024, keyChars: 160, keyDepth: 10 } as const;

/** One dotted config path segment: letters, digits, `_` and `-` (imported mods use camelCase and kebab-case keys). */
export const KEY_SEGMENT_RE = /^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$/;
export const ID_RE = /^[a-z][a-z0-9_-]{0,31}$/;
export const COLOR_RE = /^#[0-9a-fA-F]{6}$/;
/** A namespaced sound key (minecraft:entity.zombie.ambient, nx_abcd1234:gun.fire); other games use the same shape. */
export const SOUND_KEY_RE = /^[a-z0-9_.-]{1,64}:[a-z0-9_.-]{1,128}(\/[a-z0-9_.-]{1,64})*$/;
export const UNIT_RE = /^[A-Za-z%°/ .-]{1,16}$/;
export const RELOAD_COMMAND_RE = /^\/?[a-z0-9_:-]{1,32}( [a-z0-9_-]{1,32}){0,3}$/;
export const FILE_RE = /^(?![/\\])(?!.*\.\.)[A-Za-z0-9_./-]{1,120}\.(yml|yaml|json|toml|cfg|properties)$/;

export function isConfigKey(k: unknown): k is string {
  if (typeof k !== "string" || !k.length || k.length > CONFIG_LIMITS.keyChars) return false;
  const segs = k.split(".");
  return segs.length <= CONFIG_LIMITS.keyDepth && segs.every((s) => KEY_SEGMENT_RE.test(s) && s !== "__proto__" && s !== "constructor" && s !== "prototype");
}

const line = (max: number) => z.string().trim().min(1).max(max);
const Scalar = z.union([z.number(), z.string().max(CONFIG_LIMITS.textChars), z.boolean()]);
export type ScalarValue = z.infer<typeof Scalar>;
/** A value as stored: number (number/int/duration), [lo, hi] (range), boolean, string (enum/text/color/refs), list, table rows. */
export const ConfigValueZ = z.union([
  z.number(), z.boolean(), z.string().max(CONFIG_LIMITS.textChars),
  z.array(Scalar).max(CONFIG_LIMITS.listItems),
  z.array(z.record(z.string(), Scalar)).max(CONFIG_LIMITS.tableRows),
]);
export type ConfigValue = number | boolean | string | ScalarValue[] | Record<string, ScalarValue>[];
export type ConfigValues = Record<string, ConfigValue>;

const OptionZ = z.object({ value: z.union([z.string().max(64), z.number()]), label: line(60).optional() }).strict();
