const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-configdeliver/run-${Date.now().toString(36)}`;
const LANE = { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` };
const PKG = "dev.nxeon.plugins.cfgprobe";
const BASE = "/opt/mc";
const CFG = `${BASE}/plugins/CfgProbe/config.yml`;
