public class CfgProbe extends JavaPlugin {
    private String greeting = "?";
    private int radius = 0;
    private String mode = "?";

    /** Validates the config on disk; null = applied, else the reason (the old values stay). */
    private String load() {
        String m = String.valueOf(getConfig().get("mode", "fast"));
        if (!m.equals("fast") && !m.equals("slow")) return "mode must be fast or slow (got " + m + ")";
        int r = getConfig().getInt("radius", 4);
        if (r < 1) return "radius must be at least 1";
        greeting = getConfig().getString("greeting", "hello");
        radius = r;
        mode = m;
        return null;
    }

    @Override
    public void onEnable() {
        saveDefaultConfig();
        String err = load();
        if (err != null) getLogger().warning(err);
        getLogger().info("CfgProbe enabled");
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String sub = args.length > 0 ? args[0] : "";
        if (sub.equals("reload")) {
