            String err = load();
            if (err != null) sender.sendMessage("CfgProbe: failed to reload: " + err + " (keeping the old values)");
            else sender.sendMessage("CfgProbe reloaded: greeting=" + greeting + " radius=" + radius + " mode=" + mode);
        } else {
