# Edit freely; the Cyrus Config Studio only rewrites the values it changes.
greeting: hello        # shown by /cfgprobe show
radius: 4              # chunks (recommended 1-8)
mode: fast             # fast | slow
owner-note: keep me    # NOT a studio setting: must survive every delivery
`;
const spec = (): ConfigSpec => {
  const r = validateConfigSpec({ schemaVersion: 1, reload: { command: "/cfgprobe reload" }, groups: [{ id: "g", label: "CfgProbe" }], params: [
    { key: "greeting", group: "g", type: "text", label: "Greeting", default: "hello", applies: "reload" },
    { key: "radius", group: "g", type: "int", label: "Radius", default: 4, min: 1, max: 8, unit: "chunks", applies: "reload" },
    { key: "mode", group: "g", type: "text", label: "Mode", default: "fast", applies: "reload" },
