// ---------------------------------------------------------------------------------------------- the server hand
type Flight = { cmd: string; before: string; reply: string; after: string; overall: string; line: string; bootMs: number | null };
function healthFrom(report: Awaited<ReturnType<typeof fly>>["report"]): HealthReport {
  const c = (id: string) => report.checks.find((x) => x.id === id);
  const enabled = (c("plugins_enabled")?.evidence ?? []).map((l) => /^(\S+): enabled/.exec(l)?.[1]).filter((n): n is string => !!n);
  return { real: true, cameUp: c("boot_done")?.status === "pass", answered: (c("rcon_checks")?.evidence ?? []).some((l) => l.startsWith("plugins ") && /: ok/.test(l)), pluginsEnabled: enabled, errorLines: c("startup_log_clean")?.status === "fail" ? (c("startup_log_clean")?.evidence ?? []).slice(0, 5) : [], datapacksLoaded: [], evidence: (c("boot_done")?.evidence ?? []).slice(0, 2) };
}
const replyOf = (evidence: string[], id: string) => { const l = evidence.find((x) => x.startsWith(`${id} `)); return l ? l.slice(l.indexOf(" -> ") + 4).replace(/\s*\|\s*$/, "").trim() : ""; };

function flightHost(root: string, jar: { jarPath: string; jarSha256: string }, flights: Flight[]): DeliveryHost {
  const fs = new LocalGuestFs(root);
  let last: Awaited<ReturnType<typeof fly>> | null = null;
  return {
    env: ON,
    async open() {
      // the server's in-memory state = the file it had when this delivery opened it
      const pre = readFileSync(path.join(root, CFG), "utf8");
      const session: ServerSession = {
        fs, base: BASE, levelName: "world", mcVersion: LANE.version,
        async restart() { return { ok: false, error: "not used: the settings apply with /cfgprobe reload" }; },
        async console(cmd) {
          const placed = readFileSync(path.join(root, CFG), "utf8");
          const rcon: RconCheck[] = [
            { id: "plugins", command: "plugins", expect: ["CfgProbe"] },
            { id: "show-before", command: "cfgprobe show", expect: ["CFGPROBE"] },
            { id: "cmd", writeFile: { path: "plugins/CfgProbe/config.yml", content: placed }, command: cmd },
            { id: "show-after", command: "cfgprobe show", expect: ["CFGPROBE"] },
          ];
          const r = await fly({ version: LANE.version, plugins: [{ localPath: jar.jarPath, sha256: jar.jarSha256 }], files: [{ path: "plugins/CfgProbe/config.yml", content: pre }], rcon, timeouts: { bootSec: 240, totalSec: 480 } }, `flight ${cmd}`);
          last = r;
          const ev = r.report.checks.find((x) => x.id === "rcon_checks")?.evidence ?? [];
          const f: Flight = { cmd, before: replyOf(ev, "show-before"), reply: replyOf(ev, "cmd"), after: replyOf(ev, "show-after"), overall: r.summary.overall, line: describeSummary(r.summary), bootMs: r.report.bootMs ?? null };
          flights.push(f);
          console.log(`  flight: ${cmd} -> "${f.reply}" | before ${f.before} | after ${f.after}`);
          return f.reply ? { ok: true as const, reply: f.reply } : { ok: false as const, error: "the flight returned no reply" };
        },
        async health() { return last ? healthFrom(last.report) : { real: false, cameUp: false, answered: false, pluginsEnabled: [], errorLines: [], datapacksLoaded: [], evidence: ["no flight ran"] }; },
        async baselineErrors() { return []; },
      };
      return session;
    },
    managed: { ensure: async () => ({ ok: false, error: "unused" }), release: async () => ({ ok: true, action: "not_held" }), snapshot: async () => null, restore: async () => ({ ok: true }) },
    jar: { install: async () => ({ ok: false, error: "unused" }), remove: async () => ({ ok: true }) },
  };
}

const tree = (dir: string): string => {
  const out: string[] = [];
  const w = (d: string) => { for (const n of readdirSync(d).sort()) { const p = path.join(d, n), rel = path.relative(dir, p); if (rel.startsWith("opt/mc/.nxeon-cyrus") || rel.startsWith("root/.nxeon-cyrus")) continue; if (readdirSync(path.dirname(p)).includes(n) && !p.endsWith("/")) { try { const kids = readdirSync(p); out.push(`D ${rel}`); w(p); void kids; } catch { out.push(`F ${rel} ${sha(readFileSync(p))}`); } } } };
  w(dir);
  return sha(out.join("\n"));
};

async function main() {
  const oi = process.argv.indexOf("--out");
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", what: "Cyrus Config Studio Send to server: production job path + deliverConfig, every console call a real Paper 1.21.11 flight", realClient: false, aiModel: "none (hand-written fixture plugin)" };
  mkdirSync(RUN, { recursive: true });
  const jar = build();
  res.build = { javacWarnings: jar.javacWarnings, jarSha256: jar.jarSha256 };
  console.log(`javac ok (${jar.javacWarnings} warnings)`);
  const root = mkdtempSync(path.join(RUN, "srv-"));
  const put = (rel: string, d: Buffer | string) => { mkdirSync(path.dirname(path.join(root, rel)), { recursive: true }); writeFileSync(path.join(root, rel), d); };
  put(`${BASE}/server.properties`, "level-name=world\n");
  put(`${BASE}/version_history.json`, JSON.stringify({ currentVersion: `${LANE.version} (MC: ${LANE.version})` }));
  put(`${BASE}/plugins/CfgProbe-1.0.0.jar`, readFileSync(jar.jarPath));
  put(CFG, OWN_YML);
  const flights: Flight[] = [];
  const host = flightHost(root, jar, flights);
  const w = configWorld({ host, spec: spec(), yml: OWN_YML, pluginName: "CfgProbe", pluginYml: PLUGIN_YML });
  const file = () => readFileSync(path.join(root, CFG), "utf8");
  void zip;

  // S1: the production path
  console.log("S1: studio save -> send -> job -> deliverConfig");
  assert.equal((await w.save({ greeting: "hi there", radius: 6 })).status, 201);
  const s1send = await w.send();
  assert.equal(s1send.status, 202);
  const j1 = await w.run();
  const st1 = w.status(0);
